func:
/*
 * Predictive Reserve - Telemetry Store
 *
 * SHADOW ONLY
 * Nessun comando verso climatizzatore.
 *
 * Mantiene esclusivamente dati runtime in memoria.
 * I timestamp sono Date.now() dello stesso processo Node-RED,
 * quindi potranno essere usati successivamente per controlli
 * causali rx <= now.
 */

const now = Date.now();
const topic = String(msg.topic || "");

function numberOrNull(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function objectPayload(payload) {
    if (payload && typeof payload === "object") {
        return payload;
    }

    if (typeof payload === "string") {
        try {
            const parsed = JSON.parse(payload);
            if (parsed && typeof parsed === "object") {
                return parsed;
            }
        } catch (_) {
            // payload non JSON
        }
    }

    return null;
}


// ---------------------------------------------------------
// 1. AGGREGATE CLIMATE STATE
// ---------------------------------------------------------

if (topic === "casa/clima/stato_completo") {

    const obj = objectPayload(msg.payload);

    if (obj !== null) {

        flow.set("pr_climate_aggregate", obj);
        flow.set("pr_climate_aggregate_rx_ms", now);

        node.status({
            fill: "blue",
            shape: "dot",
            text: "aggregate rx"
        });

    } else {

        node.warn("PR: climate aggregate payload non valido");

        node.status({
            fill: "yellow",
            shape: "ring",
            text: "aggregate invalid"
        });
    }

    return null;
}


// ---------------------------------------------------------
// 2. DIRECT AC POWER
// ---------------------------------------------------------

if (topic === "emon/AC/emeter_power") {

    const value = numberOrNull(msg.payload);

    if (value !== null) {

        /*
         * Math.abs è coerente con il flow legacy attuale.
         * Non forziamo 0 quando l'AC è logicamente OFF:
         * conserviamo la misura fisica reale.
         */

        const acW = Math.abs(value);

        flow.set("pr_ac_power_w", acW);
        flow.set("pr_ac_power_rx_ms", now);

        node.status({
            fill: "green",
            shape: "dot",
            text: "AC " + acW.toFixed(1) + " W"
        });

    } else {

        node.warn("PR: AC power payload non numerico");

        node.status({
            fill: "yellow",
            shape: "ring",
            text: "AC invalid"
        });
    }

    return null;
}


// ---------------------------------------------------------
// 3. BEDROOM RELATIVE HUMIDITY
// ---------------------------------------------------------

if (topic === "emon/cameraMatrimoniale/humidity") {

    const value = numberOrNull(msg.payload);

    if (value !== null && value >= 0 && value <= 100) {

        flow.set("pr_bedroom_rh", value);
        flow.set("pr_bedroom_rh_rx_ms", now);

        node.status({
            fill: "green",
            shape: "dot",
            text: "RH " + value.toFixed(1) + "%"
        });

    } else {

        node.warn("PR: Bedroom RH payload non valido");

        node.status({
            fill: "yellow",
            shape: "ring",
            text: "RH invalid"
        });
    }

    return null;
}


// ---------------------------------------------------------
// UNKNOWN TOPIC
// ---------------------------------------------------------


if (topic === "zara/domotics/AC/command") {
    const raw = String(msg.payload ?? "").trim();

    if (raw.length > 0) {
        flow.set("pr_ac_command_raw", raw);
        flow.set("pr_ac_command_rx_ms", now);

        node.status({
            fill: "green",
            shape: "dot",
            text: "CMD " + raw
        });
    } else {
        node.warn("PR: comando AC vuoto");
        node.status({
            fill: "yellow",
            shape: "ring",
            text: "CMD invalid"
        });
    }

    return null;
}
node.warn("PR: topic non gestito: " + topic);
return null;

/*
 * Predictive Reserve - Telemetry Diagnostics
 *
 * SHADOW / READ ONLY
 * Nessun comando verso il climatizzatore.
 */

const now = Date.now();

function ageSeconds(rx) {
    const n = Number(rx);

    if (!Number.isFinite(n)) {
        return null;
    }

    /*
     * Un timestamp futuro NON viene mai considerato fresco.
     * Manteniamo il controllo causale rx <= now.
     */
    if (n > now) {
        return null;
    }

    return (now - n) / 1000;
}


// ==================================================
// 1. TELEMETRIA MEMORIZZATA DAL PR TELEMETRY STORE
// ==================================================

const aggregate =
    flow.get("pr_climate_aggregate") || null;

const aggregateRx =
    flow.get("pr_climate_aggregate_rx_ms");

const acW =
    flow.get("pr_ac_power_w");

const acRx =
    flow.get("pr_ac_power_rx_ms");

const bedroomRh =
    flow.get("pr_bedroom_rh");

const bedroomRhRx =
    flow.get("pr_bedroom_rh_rx_ms");

const acCommandRaw =
    flow.get("pr_ac_command_raw");

const acCommandRx =
    flow.get("pr_ac_command_rx_ms");


// ==================================================
// 2. AGE / CAUSALITY
// ==================================================

const aggregateAge =
    ageSeconds(aggregateRx);

const acAge =
    ageSeconds(acRx);

const rhAge =
    ageSeconds(bedroomRhRx);

const commandAge =
    ageSeconds(acCommandRx);


// ==================================================
// 3. DIAGNOSTIC PAYLOAD
// ==================================================

msg.payload = {

    predictive_reserve: {
        mode: "SHADOW",
        control_effect: "NONE_SHADOW_ONLY"
    },

    now_ms: now,

    climate_aggregate: {
        available:
            aggregate !== null,

        age_s:
            aggregateAge,

        fresh:
            aggregateAge !== null &&
            aggregateAge <= 180,

        causal:
            aggregateAge !== null
    },

    ac_power_direct: {
        value_w:
            Number.isFinite(Number(acW))
                ? Number(acW)
                : null,

        age_s:
            acAge,

        fresh:
            acAge !== null &&
            acAge <= 60,

        source:
            "emon/AC/emeter_power",

        causal:
            acAge !== null
    },

bedroom_rh: {
    value_pct:
        Number.isFinite(Number(bedroomRh))
            ? Number(bedroomRh)
            : null,

    age_s:
        rhAge,

    fresh:
        rhAge !== null &&
        rhAge <= 900,

    source:
        "emon/cameraMatrimoniale/humidity",

    causal:
        rhAge !== null
},

    ac_command: {
        raw:
            acCommandRaw !== undefined &&
            acCommandRaw !== null
                ? String(acCommandRaw)
                : null,

        rx_ms:
            Number.isFinite(Number(acCommandRx))
                ? Number(acCommandRx)
                : null,

        age_s:
            commandAge,

        /*
         * IMPORTANTE:
         * il comando è event-driven.
         * In questo WP NON imponiamo una freshness temporale.
         */
        causal:
            commandAge !== null,

        source:
            "zara/domotics/AC/command"
    }
};

return msg;

/*
 * Predictive Reserve
 * Macro-WP A1.1
 *
 * SAFE STARTUP / FAIL-CLOSED BOOTSTRAP
 *
 * SHADOW ONLY
 * No MQTT OUT
 * No actuator
 * No production state modification
 */

const now = Date.now();

/*
 * AC command identity is event-driven and the MQTT topic
 * is not recoverable as retained state.
 *
 * Every PR bootstrap therefore starts with command UNKNOWN.
 * Only a new MQTT event may establish command identity.
 */
flow.set("pr_ac_command_raw", null);
flow.set("pr_ac_command_rx_ms", null);


/*
 * ----------------------------------------------------------
 * 1. RESET ALL VOLATILE PREDICTOR READINESS
 *
 * Important for:
 * - full Node-RED restart
 * - Raspberry reboot
 * - ordinary Deploy where memory context may still contain
 *   state produced by the previous runtime generation.
 *
 * Nothing is assumed valid until it is reloaded/retested.
 * ----------------------------------------------------------
 */

flow.set(
    "pr_knn_runtime_ready",
    false
);

flow.set(
    "pr_knn_runtime_error",
    "BOOTSTRAP_NOT_VALIDATED"
);

flow.set(
    "pr_knn_runtime_tested_ms",
    null
);


flow.set(
    "pr_champion_artifact_ready",
    false
);

flow.set(
    "pr_champion_artifact_error",
    "BOOTSTRAP_NOT_LOADED"
);

flow.set(
    "pr_champion_artifact_loaded_ms",
    null
);

flow.set(
    "pr_champion_artifact_sha256",
    null
);


/*
 * The Champion object is memory-only.
 *
 * Explicitly clear it so that a failed reload after an
 * ordinary Deploy can never leave an old in-memory model
 * appearing usable.
 */
flow.set(
    "pr_champion_model",
    null
);


/*
 * ----------------------------------------------------------
 * 2. SAFE PR RUNTIME STATE
 * ----------------------------------------------------------
 */

const state = {

    revision:
        "PR-MACRO-WP-A1.1",

    mode:
        "SHADOW",

    control_effect:
        "NONE_SHADOW_ONLY",

    enabled:
        true,

    startup: {

        phase:
            "BOOTSTRAP_FAIL_CLOSED",

        champion_loaded:
            false,

        knn_self_test_passed:
            false,

        telemetry_reacquired:
            false,

        ready_for_shadow_prediction:
            false
    },

    predictor: {

        model_ready:
            false,

        error:
            "BOOTSTRAP_NOT_VALIDATED"
    },

    safety: {

        actuator_path:
            false,

        commands_enabled:
            false,

        authorization_allowed:
            false,

        hard_soc_floor_pct:
            10
    },

    boot_ms:
        now
};


flow.set(
    "pr_runtime_state",
    state
);


node.status({
    fill: "yellow",
    shape: "ring",
    text: "SHADOW bootstrap - fail closed"
});


msg.payload = state;

return msg;

// ACTIVE.4C: validate internal handshake before predictor execution.
if (msg._pr_prestart) {
    const r = msg._pr_prestart, p = msg.payload, t = Date.now();
    if (!p || p.schema !== "domopi.predictive_reserve.prestart_request.v1" ||
        msg.topic !== "pr/prestart_candidate" || p.prestart_candidate !== true ||
        p.transition !== "OFF_TO_NIGHT_DRY" || typeof r.request_id !== "string" || !r.request_id ||
        p.request_id !== r.request_id || p.command_raw !== r.candidate_command ||
        p.requested_at_ms !== r.requested_at_ms || !Number.isFinite(r.requested_at_ms) ||
        t < r.requested_at_ms || t - r.requested_at_ms >= 2000 ||
        !["eco26dry","eco25dry","25dry","24dry","23dry"].includes(p.command_raw)) {
        node.error("REQUEST_INVALID", msg); return null;
    }
    delete r.engine; delete r.final; delete r.snapshot;
}
/*
 * Predictive Reserve - SHADOW Engine
 * WP2D.5A - Champion KNN + Synthetic E2E Test
 *
 * SHADOW ONLY
 * Nessun comando verso il climatizzatore.
 */

const now = Date.now();

const ACTIVE_THRESHOLD_W = 50.0;

const MAX_AGE = {
    aggregate_s: 180,
    ac_power_s: 60,
    bedroom_rh_s: 900
};


// ==================================================
// WP2D.5A - SYNTHETIC TEST DETECTION
// ==================================================

const testOverride =
    msg &&
    msg.topic === "pr/selftest" &&
    msg.payload &&
    typeof msg.payload === "object" &&
    msg.payload.pr_e2e_test === true
        ? msg.payload
        : null;

const isSyntheticTest =
    testOverride !== null;

// ==================================================
// PR-ACTIVE.2B.7B.1
// PRE-START CANDIDATE QUALIFICATION PATH
//
// Percorso interno / observation-only.
// Permette di valutare un comando candidato mentre
// l'AC è ancora logicamente OFF.
//
// NON concede authority.
// NON modifica stato AC.
// NON pubblica MQTT.
// ==================================================

const preStartCandidate =
    msg &&
        msg.topic === "pr/prestart_candidate" &&
        msg.payload &&
        typeof msg.payload === "object" &&
        msg.payload.prestart_candidate === true &&
        typeof msg.payload.command_raw === "string"
        ? msg.payload
        : null;

const isPreStartCandidate =
    preStartCandidate !== null;

// ==================================================
// HELPERS
// ==================================================

function numOrNull(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function ageSeconds(rx) {

    /*
     * Missing timestamp must remain UNKNOWN.
     * Do not allow Number(null) -> 0.
     */
    if (
        rx === null ||
        rx === undefined ||
        rx === ""
    ) {
        return null;
    }

    const n = Number(rx);

    if (!Number.isFinite(n)) {
        return null;
    }

    // strict past-only
    if (n > now) {
        return null;
    }

    return (now - n) / 1000;
}

function nested(obj, path) {
    let cur = obj;

    for (const key of path) {
        if (
            cur === null ||
            cur === undefined ||
            typeof cur !== "object" ||
            !(key in cur)
        ) {
            return null;
        }

        cur = cur[key];
    }

    return cur;
}


/*
 * Exact KNN runtime logic transplanted from
 * the already validated PR KNN Self Test.
 */
function predictKnn(modelSpec, allTrainingRows, query) {

    if (
        !modelSpec ||
        !Array.isArray(allTrainingRows)
    ) {
        throw new Error("INVALID_MODEL_SPEC");
    }

    const features =
        modelSpec.features;

    const normalization =
        modelSpec.normalization;

    const condition =
        modelSpec.condition;

    const k =
        Number(modelSpec.k);

    const target =
        modelSpec.target;


    if (
        !Array.isArray(features) ||
        !normalization ||
        !condition ||
        !target
    ) {
        throw new Error(
            "INVALID_MODEL_METADATA"
        );
    }

    if (
        !Number.isFinite(k) ||
        k <= 0
    ) {
        throw new Error("INVALID_K");
    }


    // ==============================================
    // SELECT TRAINING POPULATION
    //
    // Preserve original root row order.
    // This is essential for deterministic tie-break.
    // ==============================================

    const rows =
        allTrainingRows.filter((r) => {

            for (
                const [key, expected]
                of Object.entries(condition)
            ) {

                /*
                 * command_raw is metadata describing
                 * the raw command represented by
                 * historical cmd_293.
                 *
                 * It is NOT present in training_rows,
                 * therefore it is not a row filter.
                 */
                if (key === "command_raw") {
                    continue;
                }

                if (!(key in r)) {
                    return false;
                }

                if (
                    Number.isFinite(Number(expected)) &&
                    Number.isFinite(Number(r[key]))
                ) {
                    if (
                        Number(r[key]) !==
                        Number(expected)
                    ) {
                        return false;
                    }
                }
                else if (
                    String(r[key]) !==
                    String(expected)
                ) {
                    return false;
                }
            }

            return true;
        });


    if (rows.length < k) {
        throw new Error(
            "INSUFFICIENT_TRAINING_ROWS_" +
            rows.length
        );
    }


    // ==============================================
    // STANDARDIZE QUERY
    // ==============================================

    const qz = {};

    for (const f of features) {

        if (!normalization[f]) {
            throw new Error(
                "MISSING_NORMALIZATION_" + f
            );
        }

        const mean =
            Number(normalization[f].mean);

        const std =
            Number(normalization[f].std);

        const value =
            Number(query[f]);

        if (
            !Number.isFinite(mean) ||
            !Number.isFinite(std) ||
            std <= 0 ||
            !Number.isFinite(value)
        ) {
            throw new Error(
                "INVALID_QUERY_FEATURE_" + f
            );
        }

        qz[f] =
            (value - mean) / std;
    }


    // ==============================================
    // DISTANCES
    // ==============================================

    const scored =
        rows.map((r, idx) => {

            let dist = 0;

            for (const f of features) {

                const mean =
                    Number(normalization[f].mean);

                const std =
                    Number(normalization[f].std);

                const rv =
                    Number(r[f]);

                if (!Number.isFinite(rv)) {
                    throw new Error(
                        "INVALID_TRAINING_FEATURE_" +
                        f
                    );
                }

                const rz =
                    (rv - mean) / std;

                const d =
                    rz - qz[f];

                dist += d * d;
            }


            const targetValue =
                Number(r[target]);

            if (
                !Number.isFinite(targetValue)
            ) {
                throw new Error(
                    "INVALID_TARGET"
                );
            }


            return {
                /*
                 * idx follows filtered rows in the same
                 * order as root training_rows.
                 * Therefore equal-distance tie-break
                 * preserves original training order.
                 */
                idx: idx,
                dist: dist,
                target: targetValue
            };
        });


    // ==============================================
    // EXACT ORDER:
    // distance, then original training order
    // ==============================================

    scored.sort((a, b) => {

        if (a.dist < b.dist) {
            return -1;
        }

        if (a.dist > b.dist) {
            return 1;
        }

        return a.idx - b.idx;
    });


    // ==============================================
    // K NEAREST TARGET MEAN
    // ==============================================

    let sum = 0;

    for (let i = 0; i < k; i++) {
        sum += scored[i].target;
    }

    return {
        prediction:
            sum / k,

        training_population:
            rows.length,

        k:
            k
    };
}


// ==================================================
// MODEL / RUNTIME
// ==================================================

const model =
    flow.get("pr_champion_model") || null;

const knnRuntimeReady =
    flow.get("pr_knn_runtime_ready") === true;


// ==================================================
// LIVE TELEMETRY
// ==================================================

const aggregate =
    flow.get("pr_climate_aggregate") || null;

const aggregateRx =
    flow.get("pr_climate_aggregate_rx_ms");

const acW =
    numOrNull(
        flow.get("pr_ac_power_w")
    );

const acRx =
    flow.get("pr_ac_power_rx_ms");

const bedroomRh =
    numOrNull(
        flow.get("pr_bedroom_rh")
    );

const bedroomRhRx =
    flow.get("pr_bedroom_rh_rx_ms");

const commandRawStored =
    flow.get("pr_ac_command_raw");

const commandRaw =
    commandRawStored === undefined ||
    commandRawStored === null
        ? null
        : String(commandRawStored).trim();

const commandRx =
    flow.get("pr_ac_command_rx_ms");


// ==================================================
// LIVE AGES
// ==================================================

const aggregateAge =
    ageSeconds(aggregateRx);

const acAge =
    ageSeconds(acRx);

const rhAge =
    ageSeconds(bedroomRhRx);

const commandAge =
    ageSeconds(commandRx);


const aggregateFresh =
    aggregate !== null &&
    aggregateAge !== null &&
    aggregateAge <= MAX_AGE.aggregate_s;

const acFresh =
    acW !== null &&
    acAge !== null &&
    acAge <= MAX_AGE.ac_power_s;

const rhFresh =
    bedroomRh !== null &&
    rhAge !== null &&
    rhAge <= MAX_AGE.bedroom_rh_s;

const commandObserved =
    commandRaw !== null &&
    commandRaw.length > 0 &&
    commandAge !== null;


// ==================================================
// LIVE AGGREGATE VALUES
// ==================================================

const humidexBed =
    numOrNull(
        nested(
            aggregate,
            [
                "metriche_ambientali",
                "humidex_bedroom"
            ]
        )
    );

const logicalStateRaw =
    nested(
        aggregate,
        [
            "stato_condizionatore",
            "stato_attuale"
        ]
    );

const logicalState =
    logicalStateRaw === null
        ? null
        : String(logicalStateRaw);


// ==================================================
// EFFECTIVE VALUES
//
// IMPORTANT:
// synthetic values exist only for this message.
// Nothing is written to flow/global context.
// ==================================================

const effectiveAcW =
    isSyntheticTest &&
    Number.isFinite(
        Number(testOverride.ac_w_now)
    )
        ? Number(testOverride.ac_w_now)
        : acW;


const effectiveBedroomRh =
    isSyntheticTest &&
    Number.isFinite(
        Number(testOverride.rh_bed_pct)
    )
        ? Number(testOverride.rh_bed_pct)
        : bedroomRh;


const effectiveHumidexBed =
    isSyntheticTest &&
    Number.isFinite(
        Number(testOverride.humidex_bed)
    )
        ? Number(testOverride.humidex_bed)
        : humidexBed;


const effectiveCommandRaw =
    isPreStartCandidate &&
        typeof preStartCandidate.command_raw === "string"
        ? preStartCandidate.command_raw.trim()
        : (
            isSyntheticTest &&
                typeof testOverride.command_raw === "string"
                ? testOverride.command_raw.trim()
                : commandRaw
        );


const effectiveLogicalState =
    isPreStartCandidate
        ? "OFF"
        : (
            isSyntheticTest &&
                typeof testOverride.logical_state === "string"
                ? testOverride.logical_state.trim()
                : logicalState
        );


// ==================================================
// EFFECTIVE VALIDITY
// ==================================================

const effectiveAcFresh =
    isSyntheticTest
        ? Number.isFinite(effectiveAcW)
        : acFresh;


const effectiveRhFresh =
    isSyntheticTest
        ? Number.isFinite(effectiveBedroomRh)
        : rhFresh;


const effectiveHumidexAvailable =
    Number.isFinite(effectiveHumidexBed);


const effectiveCommandObserved =
    (isSyntheticTest || isPreStartCandidate)
        ? (
            effectiveCommandRaw !== null &&
            effectiveCommandRaw.length > 0
        )
        : commandObserved;

// ==================================================
// CHAMPION CONTRACT
// ==================================================

const commandValidated =
    effectiveCommandObserved &&
    effectiveCommandRaw === "eco26dry";


const cmd293 =
    commandValidated
        ? 26
        : null;


/*
 * Exact historical dataset definition:
 *
 * active_now =
 *     int(ac_w_now >= 50.0 W)
 */
const activeNow =
    effectiveAcFresh
        ? (
            effectiveAcW >=
            ACTIVE_THRESHOLD_W
                ? 1
                : 0
          )
        : null;


const logicalStateCompatible =
    isPreStartCandidate
        ? effectiveLogicalState === "OFF"
        : effectiveLogicalState === "NIGHT_DRY";


// ==================================================
// READINESS
// ==================================================

let ready = true;

let reason =
    "READY_FOR_SHADOW_PREDICTION";


if (model === null) {

    ready = false;
    reason =
        "CHAMPION_MODEL_NOT_LOADED";
}

else if (!knnRuntimeReady) {

    ready = false;
    reason =
        "KNN_RUNTIME_NOT_VALIDATED";
}

/*
 * LIVE requires a fresh aggregate.
 *
 * Synthetic test provides all model features
 * explicitly, therefore does not depend on
 * current aggregate freshness.
 */
else if (
    !isSyntheticTest &&
    !aggregateFresh
) {

    ready = false;
    reason =
        "CLIMATE_AGGREGATE_NOT_FRESH";
}

else if (!effectiveAcFresh) {

    ready = false;
    reason =
        "AC_POWER_NOT_FRESH";
}

else if (!effectiveRhFresh) {

    ready = false;
    reason =
        "BEDROOM_RH_NOT_FRESH";
}

else if (!effectiveHumidexAvailable) {

    ready = false;
    reason =
        "BEDROOM_HUMIDEX_NOT_AVAILABLE";
}

else if (!effectiveCommandObserved) {

    ready = false;
    reason =
        "COMMAND_NOT_OBSERVED_SINCE_BOOT";
}

else if (!commandValidated) {

    ready = false;
    reason =
        "COMMAND_REGIME_NOT_VALIDATED";
}

else if (!logicalStateCompatible) {

    ready = false;
    reason =
        "LOGICAL_STATE_NOT_NIGHT_DRY";
}


// ==================================================
// KNN PREDICTION
// ==================================================

let selectedModel = null;
let energy30m = null;
let predictionError = null;
let knnTrainingPopulation = null;
let knnK = null;


if (ready) {

    selectedModel =
        activeNow === 1
            ? "CMD26_ACTIVE_F"
            : "CMD26_IDLE_C";

    try {

        if (
            !model.models ||
            !model.models[selectedModel]
        ) {
            throw new Error(
                "MODEL_NOT_FOUND_" +
                selectedModel
            );
        }

        const spec =
            model.models[selectedModel];


        const query =
            activeNow === 1
                ? {
                    cmd_293: 26,
                    active_now: 1,
                    ac_w_now:
                        effectiveAcW,
                    rh_bed_pct:
