function describe(value, depth = 0) {

    if (value === null) {
        return null;
    }

    if (Array.isArray(value)) {

        const result = {
            type: "array",
            length: value.length
        };

        /*
         * Per array grandi non stampiamo tutto il dataset.
         * Ispezioniamo solo il primo elemento.
         */
        if (value.length > 0 && depth < 4) {
            result.first = describe(
                value[0],
                depth + 1
            );
        }

        return result;
    }

    if (typeof value === "object") {

        const keys = Object.keys(value);

        const result = {
            type: "object",
            keys: keys
        };

        /*
         * Gli oggetti piccoli vengono descritti
         * ricorsivamente per capire il contratto.
         */
        if (depth < 4) {

            result.fields = {};

            for (const key of keys) {

                const v = value[key];

                if (
                    Array.isArray(v) ||
                    (v !== null &&
                     typeof v === "object")
                ) {
                    result.fields[key] =
                        describe(v, depth + 1);
                }
                else {
                    result.fields[key] = v;
                }
            }
        }

        return result;
    }

    return value;
}


