const TOL = 1e-10;


/* ======================================================
 * VALIDATED KNN PREDICTOR
 * ====================================================== */

function predict(artifact, modelName, query) {

    const m = artifact.models[modelName];

    if (!m) {
        throw new Error(
            "Unknown model: " + modelName
        );
    }


    const qz = m.features.map((feat) => {

        const n = m.normalization[feat];

        return (
            Number(query[feat]) -
            Number(n.mean)
        ) / Number(n.std);
    });


    const candidates =
        artifact.training_rows.map(
            (row, idx) => {

                let dist2 = 0.0;

                for (
                    let j = 0;
                    j < m.features.length;
                    j++
                ) {

                    const feat =
                        m.features[j];

                    const n =
                        m.normalization[feat];

                    const rz =
                        (
                            Number(row[feat]) -
                            Number(n.mean)
                        ) /
                        Number(n.std);

                    const d =
                        qz[j] - rz;

                    dist2 += d * d;
                }

                return {
                    dist2: dist2,
                    idx: idx,
                    y: Number(
                        row.energy_30m_kwh
                    )
                };
            }
        );


    candidates.sort((a, b) => {

        if (a.dist2 < b.dist2) {
            return -1;
        }

        if (a.dist2 > b.dist2) {
            return 1;
        }

        return a.idx - b.idx;
    });


    const k = Number(m.k);

    let sum = 0.0;

    for (let i = 0; i < k; i++) {
        sum += candidates[i].y;
    }

    return sum / k;
}


