        Number(previous.last_rx_ms)
    ) &&
    Number.isFinite(
        Number(previous.last_power_w)
    ) &&
    Number.isFinite(
        Number(previous.energy_wh)
    )
) {

    const previousRx =
        Number(
            previous.last_rx_ms
        );

    const previousW =
        Number(
            previous.last_power_w
        );

    const dtMs =
        now - previousRx;


    state.energy_wh =
        Number(
