const liveLogicalState =
    telemetry.logical_state &&
    telemetry.logical_state.effective_value !== undefined &&
    telemetry.logical_state.effective_value !== null
        ? String(
            telemetry.logical_state.effective_value
          ).trim()
        : null;


// ==================================================
// CURRENT ENERGY INTEGRATOR
// ==================================================

const energyState =
    flow.get(
        "pr_ac_energy_integrator"
    ) || null;

if (
    !energyState ||
    !Number.isFinite(
        Number(
            energyState.energy_wh
        )
    )
) {

    node.status({
        fill: "yellow",
        shape: "ring",
        text: "energy unavailable"
    });

    return null;
}

const energyNowWh =
    Number(
        energyState.energy_wh
    );

const integratorSamples =
    numOrNull(
        energyState.samples
    );

const rejectedIntervals =
    numOrNull(
        energyState.rejected_intervals
    );


// ==================================================
// EXISTING VALIDATION
// ==================================================

let pending =
    flow.get(
        "pr_live_validation_pending"
    ) || null;


// ==================================================
// VALIDATE CONTINUITY OF A PENDING SESSION
// ==================================================

if (pending) {

    const elapsedMs =
        now -
        Number(
            pending.start_ms
        );


    // ----------------------------------------------
    // Clock sanity
    // ----------------------------------------------

    if (
        !Number.isFinite(elapsedMs) ||
        elapsedMs < 0
    ) {

        return emitInvalid(
            "INVALID_ELAPSED_TIME",
            {
                start_ms:
                    pending.start_ms
            }
        );
    }


    // ----------------------------------------------
    // Command continuity
    // ----------------------------------------------

    if (
        liveCommand !==
        pending.command_raw
    ) {

        return emitInvalid(
            "COMMAND_CHANGED_DURING_VALIDATION",
            {
                expected_command:
                    pending.command_raw,

                current_command:
                    liveCommand,

                elapsed_s:
                    elapsedMs / 1000
            }
        );
    }


    // ----------------------------------------------
    // Logical-state continuity
    // ----------------------------------------------

    if (
        liveLogicalState !==
        "NIGHT_DRY"
    ) {

        return emitInvalid(
            "LOGICAL_STATE_CHANGED_DURING_VALIDATION",
            {
                expected_state:
                    "NIGHT_DRY",

                current_state:
                    liveLogicalState,

                elapsed_s:
                    elapsedMs / 1000
            }
        );
    }


    // ----------------------------------------------
    // Energy counter continuity
    // ----------------------------------------------

    const startEnergyWh =
        Number(
            pending.energy_start_wh
        );

    if (
        !Number.isFinite(
            startEnergyWh
        ) ||
        energyNowWh <
            startEnergyWh
    ) {

        return emitInvalid(
            "ENERGY_COUNTER_RESET_OR_INVALID",
            {
                energy_start_wh:
                    pending.energy_start_wh,

                energy_now_wh:
                    energyNowWh,

                elapsed_s:
                    elapsedMs / 1000
            }
        );
    }


    // ----------------------------------------------
    // Sample counter continuity
    // ----------------------------------------------

    const startSamples =
        numOrNull(
            pending.samples_start
        );

    if (
        startSamples !== null &&
        integratorSamples !== null &&
        integratorSamples <
            startSamples
    ) {

        return emitInvalid(
            "ENERGY_INTEGRATOR_RESTARTED",
            {
                samples_start:
                    startSamples,

                samples_now:
                    integratorSamples,

                elapsed_s:
                    elapsedMs / 1000
            }
        );
    }


    // ----------------------------------------------
    // Rejected interval continuity
    // ----------------------------------------------

    const rejectedStart =
        numOrNull(
            pending.rejected_intervals_start
        );

    if (
        rejectedStart !== null &&
        rejectedIntervals !== null &&
        rejectedIntervals >
            rejectedStart
    ) {

        return emitInvalid(
            "ENERGY_TELEMETRY_GAP_DURING_VALIDATION",
            {
                rejected_intervals_start:
                    rejectedStart,

                rejected_intervals_now:
                    rejectedIntervals,

                elapsed_s:
                    elapsedMs / 1000
            }
        );
    }


    // ----------------------------------------------
    // Complete at >=30 min
    // ----------------------------------------------

    if (
        elapsedMs >= HORIZON_MS
    ) {

        if (
            elapsedMs >
            HORIZON_MS +
            MAX_COMPLETION_DELAY_MS
        ) {

            flow.set(
                "pr_live_validation_pending",
                null
            );

            msg.payload = {

                event:
                    "LIVE_VALIDATION_EXPIRED",

                mode:
                    "SHADOW",

                start_ms:
                    pending.start_ms,

                elapsed_s:
                    elapsedMs / 1000,

                reason:
                    "COMPLETION_TOO_LATE",

                safety: {
                    observation_only: true,
                    actuator_path: false,
                    commands_enabled: false
                }
            };

            node.status({
                fill: "yellow",
                shape: "ring",
                text: "validation expired"
            });

            return msg;
        }


        const actualWh =
            energyNowWh -
            startEnergyWh;

        const actualKwh =
            actualWh / 1000;

        const predictedKwh =
            Number(
                pending.predicted_30m_kwh
            );

        const errorKwh =
            actualKwh -
            predictedKwh;

        const underpredictionKwh =
            Math.max(
                errorKwh,
                0
            );


        msg.payload = {

            event:
                "LIVE_VALIDATION_COMPLETE",

            mode:
                "SHADOW",

            model:
                pending.model,

            command_raw:
                pending.command_raw,

            logical_state:
                "NIGHT_DRY",

            active_now_start:
                pending.active_now_start,

            start_ms:
                pending.start_ms,

            end_ms:
                now,

            elapsed_s:
                elapsedMs / 1000,

            predicted_30m_kwh:
                predictedKwh,

            actual_30m_kwh:
                actualKwh,

            error_kwh:
                errorKwh,

            underprediction_kwh:
                underpredictionKwh,

            energy_start_wh:
                startEnergyWh,

            energy_end_wh:
                energyNowWh,

            samples_start:
                startSamples,

            samples_end:
                integratorSamples,

            rejected_intervals_start:
                rejectedStart,

            rejected_intervals_end:
                rejectedIntervals,

            safety: {
                observation_only: true,
                actuator_path: false,
                commands_enabled: false
            }
        };


        flow.set(
            "pr_live_validation_pending",
            null
        );


        node.status({
            fill: "green",
            shape: "dot",
            text:
                "validated err " +
                errorKwh.toFixed(3) +
                " kWh"
        });

        return msg;
    }


    // ----------------------------------------------
    // Still pending
    // ----------------------------------------------

    node.status({
        fill: "blue",
        shape: "dot",
        text:
            "pending " +
            Math.floor(
                elapsedMs / 60000
            ) +
            "/30 min"
    });

    return null;
}


// ==================================================
// START NEW VALIDATION
// ==================================================

const eligible =
    predictor.model_ready === true &&
    predictor.reason ===
        "READY_FOR_SHADOW_PREDICTION" &&
    Number.isFinite(
        Number(
            predictor.energy_30m_kwh
        )
    ) &&
    modelInput.command_raw ===
        "eco26dry" &&
    liveCommand ===
        "eco26dry" &&
    liveLogicalState ===
        "NIGHT_DRY" &&
    (
        predictor.selected_model ===
            "CMD26_ACTIVE_F" ||
        predictor.selected_model ===
            "CMD26_IDLE_C"
    );


if (!eligible) {

    node.status({
        fill: "grey",
        shape: "ring",
        text:
            predictor.reason ||
            "not eligible"
    });

    return null;
}


pending = {

    start_ms:
        now,

    energy_start_wh:
        energyNowWh,

    samples_start:
        integratorSamples,

    rejected_intervals_start:
        rejectedIntervals,

    predicted_30m_kwh:
        Number(
            predictor.energy_30m_kwh
        ),

    model:
        predictor.selected_model,

    command_raw:
        modelInput.command_raw,

    logical_state_start:
        liveLogicalState,

    active_now_start:
        modelInput.active_now
};


flow.set(
    "pr_live_validation_pending",
    pending
);


msg.payload = {

    event:
        "LIVE_VALIDATION_STARTED",

    mode:
        "SHADOW",

    model:
        pending.model,

    command_raw:
        pending.command_raw,

    logical_state:
        pending.logical_state_start,

    active_now_start:
        pending.active_now_start,

    predicted_30m_kwh:
        pending.predicted_30m_kwh,

    energy_start_wh:
        pending.energy_start_wh,

    samples_start:
        pending.samples_start,

    rejected_intervals_start:
        pending.rejected_intervals_start,

    start_ms:
        pending.start_ms,

    horizon_min:
        30,

    safety: {
        observation_only: true,
        actuator_path: false,
        commands_enabled: false
    }
};


node.status({
    fill: "blue",
    shape: "dot",
    text:
        "validation 0/30 min"
});


return msg;

/*
 * Predictive Reserve
 * WP2D.5B.3 - Live Validation Diagnostics
 *
 * READ ONLY
 * Nessuna modifica a stato, predictor o attuatori.
 */

const now = Date.now();

const HORIZON_MS =
    30 * 60 * 1000;

const pending =
    flow.get(
        "pr_live_validation_pending"
    ) || null;

const energyState =
    flow.get(
        "pr_ac_energy_integrator"
    ) || null;


function numOrNull(v) {
    const n = Number(v);
    return Number.isFinite(n)
        ? n
        : null;
}


const currentEnergyWh =
    energyState
        ? numOrNull(
            energyState.energy_wh
          )
        : null;


if (!pending) {

    msg.payload = {

        state:
            "IDLE",

        pending:
            false,

        current_energy_wh:
            currentEnergyWh,

        message:
            "NO_LIVE_VALIDATION_PENDING",

        safety: {
            observation_only: true,
            actuator_path: false,
            commands_enabled: false
        }
    };

    node.status({
        fill: "grey",
        shape: "ring",
        text: "IDLE"
    });

    return msg;
}


const startMs =
    numOrNull(
        pending.start_ms
    );

const elapsedMs =
    startMs !== null &&
    startMs <= now
        ? now - startMs
        : null;


const remainingMs =
    elapsedMs !== null
        ? Math.max(
            HORIZON_MS - elapsedMs,
            0
          )
        : null;


const elapsedMin =
    elapsedMs !== null
        ? elapsedMs / 60000
        : null;


const remainingMin =
    remainingMs !== null
        ? remainingMs / 60000
        : null;


const energyStartWh =
    numOrNull(
        pending.energy_start_wh
    );


const energyDeltaWh =
    currentEnergyWh !== null &&
    energyStartWh !== null
        ? currentEnergyWh -
          energyStartWh
        : null;


msg.payload = {

    state:
        "PENDING",

    pending:
        true,

    model:
        pending.model || null,

    command_raw:
        pending.command_raw || null,

    active_now_start:
        numOrNull(
            pending.active_now_start
        ),

    predicted_30m_kwh:
        numOrNull(
            pending.predicted_30m_kwh
        ),

    start_ms:
        startMs,

    elapsed_min:
        elapsedMin,

    remaining_min:
        remainingMin,

    horizon_min:
        30,

    energy_start_wh:
        energyStartWh,

    current_energy_wh:
        currentEnergyWh,

    observed_energy_delta_wh:
        energyDeltaWh,

    completion_due:
        remainingMs === 0,

    safety: {
        observation_only: true,
        actuator_path: false,
        commands_enabled: false
    }
};


node.status({

    fill:
        remainingMs === 0
            ? "yellow"
            : "blue",

    shape:
        "dot",

    text:
        remainingMs === 0
            ? "DUE"
            : (
                "PENDING " +
                Math.floor(
                    elapsedMin
                ) +
                "/30 min"
              )
});


return msg;

/*
 * Predictive Reserve
 * WP2D.5B.4A - Validation Robustness Self Test
 *
 * INTERNAL TEST ONLY
 *
 * Uses dedicated test state:
 *   pr_validation_selftest_pending
 *
 * NEVER touches:
 *   pr_live_validation_pending
 *
 * No MQTT OUT
 * No actuator
 * No production command
 */

const now = Date.now();

const TEST_STATE_KEY =
    "pr_validation_selftest_pending";

function makeSafety() {
    return {
        internal_test_only: true,
        production_state_modified: false,
        mqtt_command_published: false,
        actuator_path: false,
        commands_enabled: false
    };
}

function emitResult(event, extra) {

    msg.payload =
        Object.assign(
            {
                event: event,
                timestamp_ms: now,
                safety: makeSafety()
            },
            extra || {}
        );

    return msg;
}


// ==================================================
// TEST COMMAND
// ==================================================

const action =
    msg &&
    msg.payload &&
    typeof msg.payload === "object"
        ? String(
            msg.payload.action || ""
          ).trim()
        : "";


let pending =
    flow.get(TEST_STATE_KEY) || null;


// ==================================================
// START
// ==================================================

if (action === "START") {

    pending = {
        start_ms: now,
        command_raw: "eco26dry",
        logical_state: "NIGHT_DRY",
        energy_start_wh: 100,
        samples_start: 10,
        rejected_intervals_start: 0
    };

    flow.set(
        TEST_STATE_KEY,
        pending
    );

    node.status({
        fill: "blue",
        shape: "dot",
        text: "TEST pending"
    });

    return emitResult(
        "SELFTEST_VALIDATION_STARTED",
        {
            pending: pending
        }
    );
}


// ==================================================
// COMMAND CHANGE
// ==================================================

if (action === "COMMAND_CHANGE") {

    if (!pending) {

        node.status({
            fill: "yellow",
            shape: "ring",
            text: "TEST no pending"
        });

        return emitResult(
            "SELFTEST_ERROR",
            {
                reason:
                    "NO_TEST_PENDING"
            }
        );
    }


    const currentCommand =
        String(
        msg.payload.current_command ||
        ""
    );


    if (
        currentCommand !==
        pending.command_raw
    ) {

        flow.set(
            TEST_STATE_KEY,
            null
        );

        node.status({
            fill: "green",
            shape: "dot",
            text: "CMD change PASS"
        });

        return emitResult(
            "SELFTEST_INVALIDATED",
            {
                reason:
                    "COMMAND_CHANGED_DURING_VALIDATION",

                expected_command:
                    pending.command_raw,

                current_command:
                    currentCommand,

                result:
                    "PASS"
            }
        );
    }


    return emitResult(
        "SELFTEST_FAILED",
        {
            reason:
                "COMMAND_CHANGE_NOT_DETECTED"
        }
    );
}


// ==================================================
// LOGICAL STATE CHANGE
// ==================================================

if (action === "LOGICAL_STATE_CHANGE") {

    if (!pending) {

        node.status({
            fill: "yellow",
            shape: "ring",
            text: "TEST no pending"
        });

        return emitResult(
            "SELFTEST_ERROR",
            {
                reason:
                    "NO_TEST_PENDING"
            }
        );
    }


    const currentLogicalState =
    String(
        msg.payload.current_logical_state ||
        "OFF"
    );

if (
    currentLogicalState !==
    pending.logical_state
) {

    flow.set(
        TEST_STATE_KEY,
        null
    );

    node.status({
        fill: "green",
        shape: "dot",
        text: "STATE change PASS"
    });

    return emitResult(
        "SELFTEST_INVALIDATED",
        {
            reason:
                "LOGICAL_STATE_CHANGED_DURING_VALIDATION",

            expected_state:
                pending.logical_state,

            current_state:
                currentLogicalState,

            result:
                "PASS"
        }
    );
}


    return emitResult(
        "SELFTEST_FAILED",
        {
            reason:
                "LOGICAL_STATE_CHANGE_NOT_DETECTED"
        }
    );
}

// ==================================================
// ENERGY COUNTER RESET
// ==================================================

if (action === "ENERGY_COUNTER_RESET") {

    if (!pending) {
        node.status({
            fill: "yellow",
            shape: "ring",
            text: "TEST no pending"
        });

        return emitResult(
            "SELFTEST_ERROR",
            {
                reason: "NO_TEST_PENDING"
            }
        );
    }

    const currentEnergyWh =
        Number(msg.payload.current_energy_wh);

    if (
        !Number.isFinite(currentEnergyWh) ||
        currentEnergyWh < pending.energy_start_wh
    ) {

        flow.set(
            TEST_STATE_KEY,
            null
        );

        node.status({
            fill: "green",
            shape: "dot",
            text: "ENERGY reset PASS"
        });

        return emitResult(
            "SELFTEST_INVALIDATED",
            {
                reason:
                    "ENERGY_COUNTER_RESET_OR_INVALID",

                energy_start_wh:
                    pending.energy_start_wh,

                current_energy_wh:
                    currentEnergyWh,

                result:
                    "PASS"
            }
        );
    }

    return emitResult(
        "SELFTEST_FAILED",
        {
            reason:
                "ENERGY_COUNTER_RESET_NOT_DETECTED",

            energy_start_wh:
                pending.energy_start_wh,

            current_energy_wh:
                currentEnergyWh
        }
    );
}


// ==================================================
// ENERGY INTEGRATOR RESTART
// ==================================================

if (action === "ENERGY_INTEGRATOR_RESTART") {

    if (!pending) {
        node.status({
            fill: "yellow",
            shape: "ring",
            text: "TEST no pending"
        });

        return emitResult(
            "SELFTEST_ERROR",
            {
                reason: "NO_TEST_PENDING"
            }
        );
    }

    const currentSamples =
        Number(msg.payload.current_samples);

    if (
        Number.isFinite(currentSamples) &&
        currentSamples < pending.samples_start
    ) {

        flow.set(
            TEST_STATE_KEY,
            null
        );

        node.status({
            fill: "green",
            shape: "dot",
            text: "INTEGRATOR restart PASS"
        });

        return emitResult(
            "SELFTEST_INVALIDATED",
            {
                reason:
                    "ENERGY_INTEGRATOR_RESTARTED",

                samples_start:
                    pending.samples_start,

                current_samples:
                    currentSamples,

                result:
                    "PASS"
            }
        );
    }

    return emitResult(
        "SELFTEST_FAILED",
        {
            reason:
                "ENERGY_INTEGRATOR_RESTART_NOT_DETECTED",

            samples_start:
                pending.samples_start,

            current_samples:
                currentSamples
        }
    );
}


// ==================================================
// ENERGY TELEMETRY GAP
// ==================================================

if (action === "ENERGY_TELEMETRY_GAP") {

    if (!pending) {
        node.status({
            fill: "yellow",
            shape: "ring",
            text: "TEST no pending"
        });

        return emitResult(
            "SELFTEST_ERROR",
            {
                reason: "NO_TEST_PENDING"
            }
        );
    }

    const currentRejectedIntervals =
        Number(
            msg.payload.current_rejected_intervals
        );

    if (
        Number.isFinite(currentRejectedIntervals) &&
        currentRejectedIntervals >
            pending.rejected_intervals_start
    ) {

        flow.set(
            TEST_STATE_KEY,
            null
        );

        node.status({
            fill: "green",
            shape: "dot",
            text: "ENERGY gap PASS"
        });

        return emitResult(
            "SELFTEST_INVALIDATED",
            {
                reason:
                    "ENERGY_TELEMETRY_GAP_DURING_VALIDATION",

                rejected_intervals_start:
                    pending.rejected_intervals_start,

                current_rejected_intervals:
                    currentRejectedIntervals,

                result:
                    "PASS"
            }
        );
    }

    return emitResult(
        "SELFTEST_FAILED",
        {
            reason:
                "ENERGY_TELEMETRY_GAP_NOT_DETECTED",

            rejected_intervals_start:
                pending.rejected_intervals_start,

            current_rejected_intervals:
                currentRejectedIntervals
        }
    );
}

// ==================================================
// UNKNOWN ACTION
// ==================================================

node.status({
    fill: "yellow",
    shape: "ring",
    text: "TEST invalid action"
});

return emitResult(
    "SELFTEST_ERROR",
    {
        reason:
            "UNKNOWN_ACTION",

        action:
            action || null
    }
);

/*
 * Predictive Reserve
 * WP2D.5B.5 - New-Regime Data Collection Readiness
 *
 * READ-ONLY / OBSERVATION ONLY
 *
 * Purpose:
 * - determine whether the CURRENT LIVE sample is suitable
 *   for future candidate-model data collection
 *
 * It does NOT:
 * - train a model
 * - persist a dataset
 * - modify production state
 * - publish MQTT
 * - send AC commands
 * - authorize Predictive Reserve
 */

const now = Date.now();

const NEW_REGIME_COMMANDS = [
    "eco25dry",
    "25dry",
    "24dry",
    "23dry"
];

const ACTIVE_THRESHOLD_W = 50;


// ==================================================
// INPUT
// ==================================================

const p =
    msg &&
    msg.payload &&
    typeof msg.payload === "object"
        ? msg.payload
        : null;

if (!p) {
    return null;
}

const testContext =
    p.test_context || {};

const telemetry =
    p.telemetry || {};

const modelInput =
    p.model_input || {};


// ==================================================
// LIVE ONLY
// ==================================================

if (
    testContext.synthetic === true ||
    testContext.source !== "LIVE"
) {

    node.status({
        fill: "grey",
        shape: "ring",
        text: "synthetic ignored"
    });

    return null;
}


// ==================================================
// CURRENT VALUES
// ==================================================

const commandRaw =
    telemetry.ac_command &&
    telemetry.ac_command.effective_raw !== undefined &&
    telemetry.ac_command.effective_raw !== null
        ? String(
            telemetry.ac_command.effective_raw
          ).trim()
        : null;

const logicalState =
    telemetry.logical_state &&
    telemetry.logical_state.effective_value !== undefined &&
    telemetry.logical_state.effective_value !== null
        ? String(
            telemetry.logical_state.effective_value
          ).trim()
        : null;

const acW =
    telemetry.ac_power &&
    Number.isFinite(
        Number(
            telemetry.ac_power.effective_value_w
        )
    )
        ? Number(
            telemetry.ac_power.effective_value_w
          )
        : null;

const rh =
    telemetry.bedroom_rh &&
    Number.isFinite(
        Number(
            telemetry.bedroom_rh.effective_value_pct
        )
    )
        ? Number(
            telemetry.bedroom_rh.effective_value_pct
          )
        : null;

const humidex =
    telemetry.bedroom_humidex &&
    Number.isFinite(
        Number(
            telemetry.bedroom_humidex.effective_value
        )
    )
        ? Number(
            telemetry.bedroom_humidex.effective_value
          )
        : null;


// ==================================================
// CAUSAL / FRESHNESS CHECKS
// ==================================================

const aggregateReady =
    telemetry.climate_aggregate &&
    telemetry.climate_aggregate.available === true &&
    telemetry.climate_aggregate.fresh === true &&
    telemetry.climate_aggregate.causal === true;

const acPowerReady =
    acW !== null &&
    telemetry.ac_power &&
    telemetry.ac_power.fresh === true &&
    telemetry.ac_power.causal === true;

const rhReady =
    rh !== null &&
    telemetry.bedroom_rh &&
    telemetry.bedroom_rh.fresh === true &&
    telemetry.bedroom_rh.causal === true;

const humidexReady =
    humidex !== null;

const commandObserved =
    telemetry.ac_command &&
    telemetry.ac_command.observed_since_boot === true &&
    telemetry.ac_command.effective_observed === true &&
    commandRaw !== null &&
    commandRaw.length > 0;

const newRegimeCommand =
    NEW_REGIME_COMMANDS.includes(
        commandRaw
    );

const nightDry =
    logicalState === "NIGHT_DRY";


// ==================================================
// ENERGY INTEGRATOR
// ==================================================

const energy =
    flow.get(
        "pr_ac_energy_integrator"
    ) || null;

let energyReady = false;
let energyAgeS = null;
let energyCausal = false;

if (
    energy &&
    Number.isFinite(
        Number(energy.energy_wh)
    ) &&
    Number.isFinite(
        Number(energy.samples)
    ) &&
    Number.isFinite(
        Number(energy.rejected_intervals)
    ) &&
    Number.isFinite(
        Number(energy.last_rx_ms)
    )
) {

    const rx =
        Number(
            energy.last_rx_ms
        );

    const ageMs =
        now - rx;

    if (ageMs >= 0) {

        energyCausal = true;

        energyAgeS =
            ageMs / 1000;

        if (energyAgeS <= 60) {
            energyReady = true;
        }
    }
}


// ==================================================
// CURRENT active_now
//
// IMPORTANT:
// Champion training semantics:
//
// active_now = ac_w_now >= 50 W
//
// This is intentionally independent from the
// production 10 W watchdog threshold.
// ==================================================

const activeNow =
    acW !== null
        ? (
            acW >= ACTIVE_THRESHOLD_W
                ? 1
                : 0
          )
        : null;


// ==================================================
// BLOCKERS
// ==================================================

const blockers = [];

if (!aggregateReady) {
    blockers.push(
        "CLIMATE_AGGREGATE_NOT_READY"
    );
}

if (!acPowerReady) {
    blockers.push(
        "AC_POWER_NOT_READY"
    );
}

if (!rhReady) {
    blockers.push(
        "BEDROOM_RH_NOT_READY"
    );
}

if (!humidexReady) {
    blockers.push(
        "BEDROOM_HUMIDEX_NOT_READY"
    );
}

if (!commandObserved) {
    blockers.push(
        "AC_COMMAND_NOT_OBSERVED"
    );
}

if (
    commandObserved &&
    !newRegimeCommand
) {
    blockers.push(
        "COMMAND_NOT_IN_NEW_REGIME_SET"
    );
}

if (!nightDry) {
    blockers.push(
        "LOGICAL_STATE_NOT_NIGHT_DRY"
    );
}

if (!energyReady) {
    blockers.push(
        "ENERGY_INTEGRATOR_NOT_READY"
    );
}


// ==================================================
// READINESS
// ==================================================

const sampleObservable =
    blockers.length === 0;


// ==================================================
// IMPORTANT:
//
// We are NOT yet persisting samples.
//
// Therefore:
//
// sample_observable_now = source data is suitable
//
// dataset_capture_enabled = false
//
// This avoids falsely claiming that a training
// dataset is already being collected.
// ==================================================

let state;

if (sampleObservable) {

    state =
        "NEW_REGIME_SAMPLE_OBSERVABLE";

} else if (
    commandObserved &&
    !newRegimeCommand
) {

    state =
        "WAITING_NEW_REGIME_COMMAND";

} else {

    state =
        "SOURCE_DATA_NOT_READY";
}


// ==================================================
// OUTPUT
// ==================================================

msg.payload = {

    timestamp_ms:
        now,

    wp:
        "WP2D.5B.5",

    mode:
        "SHADOW",

    collection_state:
        state,

    sample_observable_now:
        sampleObservable,

    dataset_capture_enabled:
        false,

    persistence_status:
        "NOT_IMPLEMENTED_YET",

    current_regime: {

        command_raw:
            commandRaw,

        recognized_new_regime:
            newRegimeCommand,

        allowed_new_regime_commands:
            NEW_REGIME_COMMANDS,

        logical_state:
            logicalState,

        night_dry:
            nightDry
    },

    candidate_features: {

        command_raw:
            commandRaw,

        cmd_293:
            null,

        cmd_293_status:
            "NOT_AUDITED_FOR_NEW_REGIME",

        active_now:
            activeNow,

        active_threshold_w:
            ACTIVE_THRESHOLD_W,

        ac_w_now:
            acW,

        rh_bed_pct:
            rh,

        humidex_bed:
            humidex
    },

    source_readiness: {

        climate_aggregate:
            aggregateReady,

        ac_power:
            acPowerReady,

        bedroom_rh:
            rhReady,

        bedroom_humidex:
            humidexReady,

        command_observed:
            commandObserved,

        energy_integrator:
            energyReady
    },

    energy_integrator: {

        ready:
            energyReady,

        causal:
            energyCausal,

        age_s:
            energyAgeS,

        energy_wh:
            energy &&
            Number.isFinite(
                Number(
                    energy.energy_wh
                )
            )
                ? Number(
                    energy.energy_wh
                  )
                : null,

        samples:
            energy &&
            Number.isFinite(
                Number(
                    energy.samples
                )
            )
                ? Number(
                    energy.samples
                  )
                : null,

        rejected_intervals:
            energy &&
            Number.isFinite(
                Number(
                    energy.rejected_intervals
                )
            )
                ? Number(
                    energy.rejected_intervals
                  )
                : null
    },

    blockers:
        blockers,

    model_policy: {

        current_champion_command:
            "eco26dry",

        current_champion_usable_for_new_regime:
            false,

        candidate_training_required:
            true,

        prediction_authorization:
            false
    },

    safety: {

        observation_only:
            true,

        production_state_modified:
            false,

        mqtt_command_published:
            false,

        actuator_path:
            false,

        commands_enabled:
            false
    }
};


// ==================================================
// STATUS
// ==================================================

if (sampleObservable) {

    node.status({
        fill: "green",
        shape: "dot",
        text:
            "OBSERVE " +
            commandRaw
    });

} else if (
    commandObserved &&
    !newRegimeCommand
) {

    node.status({
        fill: "blue",
        shape: "ring",
        text:
            "wait new regime: " +
            commandRaw
    });

} else {

    node.status({
        fill: "yellow",
        shape: "ring",
        text:
            blockers[0] ||
            "not ready"
    });
}

return msg;

/*
 * Predictive Reserve
 * WP2D.5B.6B - LIVE New-Regime Causal Collector
 *
 * SHADOW / OBSERVATION ONLY
 *
 * Output 1:
 *   append-only JSONL records
 *
 * Output 2:
 *   runtime diagnostics
 *
 * No MQTT OUT.
 * No AC commands.
 * No Predictive Reserve authorization.
 */

const now = Date.now();

const SCHEMA =
    "domopi.predictive_reserve.new_regime_live.v1";

const STATE_KEY =
    "pr_new_regime_collector_v1";

const NEW_REGIME_COMMANDS = [
    "eco25dry",
    "25dry",
    "24dry",
    "23dry"
];

const ACTIVE_THRESHOLD_W = 50;

const HORIZON_MS =
    30 * 60 * 1000;

const MAX_COMPLETION_DELAY_MS =
    2 * 60 * 1000;

/*
 * Avoid duplicate anchors if PR Evaluate is pressed
 * manually several times.
 */
const MIN_ANCHOR_INTERVAL_MS =
    55 * 1000;

/*
 * Collector-specific causal policy.
 *
 * AC:
 * same strict-past <=60 s semantics.
 *
 * Environment:
 * 180 min corresponds to the audited historical
 * dataset environmental maximum age.
 *
 * Aggregate:
 * kept stricter because it carries current
 * controller state / Humidex.
 */
const MAX_AC_AGE_S = 60;
const MAX_RH_AGE_S = 180 * 60;
const MAX_AGGREGATE_AGE_S = 180;


// ==================================================
// HELPERS
// ==================================================

function finiteOrNull(v) {
    const n = Number(v);
    return Number.isFinite(n)
        ? n
        : null;
}

function makeFileMessage(record) {
    return {
        topic: "pr/new_regime_dataset",
        payload: JSON.stringify(record)
    };
}

function terminalRecord(
    anchor,
    status,
    reason,
    extra
) {
    return Object.assign(
        {},
        anchor,
        {
            record_status: status,
            invalid_reason:
                reason || null,
            terminal_timestamp_ms:
                now
        },
        extra || {}
    );
}


// ==================================================
// INPUT
// ==================================================

const p =
    msg &&
    msg.payload &&
    typeof msg.payload === "object"
        ? msg.payload
        : null;

if (!p) {
    return null;
}

const testContext =
    p.test_context || {};

if (
    testContext.synthetic === true ||
    testContext.source !== "LIVE"
) {
    return null;
}

const telemetry =
    p.telemetry || {};


// ==================================================
// COLLECTOR STATE
// persistent PR-only context
// ==================================================

let collector =
    flow.get(
        STATE_KEY,
        "file"
    ) || {
        sequence: 0,
        last_anchor_ms: null,
        pending: []
    };

/*
 * Persistence write guard.
 *
 * Keep a canonical snapshot of the persistent collector
 * state as it was loaded. We write the "file" context
 * only when sequence / last_anchor_ms / pending actually
 * change.
 *
 * This avoids unnecessary periodic filesystem writes
 * during idle SHADOW operation.
 */
const collectorBefore =
    JSON.stringify(collector);

if (!Array.isArray(collector.pending)) {
    collector.pending = [];
}

if (!Number.isFinite(Number(collector.sequence))) {
    collector.sequence = 0;
}


// ==================================================
// CURRENT TELEMETRY
// ==================================================

const commandRaw =
    telemetry.ac_command &&
    telemetry.ac_command.effective_raw !== undefined &&
    telemetry.ac_command.effective_raw !== null
        ? String(
            telemetry.ac_command.effective_raw
          ).trim()
        : null;

const commandRxMs =
    telemetry.ac_command
        ? finiteOrNull(
            telemetry.ac_command.rx_ms
          )
        : null;

const logicalState =
    telemetry.logical_state &&
    telemetry.logical_state.effective_value !== undefined &&
    telemetry.logical_state.effective_value !== null
        ? String(
            telemetry.logical_state.effective_value
          ).trim()
        : null;

const acW =
    telemetry.ac_power
        ? finiteOrNull(
            telemetry.ac_power.effective_value_w
          )
        : null;

const acAgeS =
    telemetry.ac_power
        ? finiteOrNull(
            telemetry.ac_power.age_s
          )
        : null;

const acCausal =
    telemetry.ac_power &&
    telemetry.ac_power.causal === true;

const rh =
    telemetry.bedroom_rh
        ? finiteOrNull(
            telemetry.bedroom_rh.effective_value_pct
          )
        : null;

const rhAgeS =
    telemetry.bedroom_rh
        ? finiteOrNull(
            telemetry.bedroom_rh.age_s
          )
        : null;

const rhCausal =
    telemetry.bedroom_rh &&
    telemetry.bedroom_rh.causal === true;

const humidex =
    telemetry.bedroom_humidex
        ? finiteOrNull(
            telemetry.bedroom_humidex.effective_value
          )
        : null;

const aggregateAgeS =
    telemetry.climate_aggregate
        ? finiteOrNull(
            telemetry.climate_aggregate.age_s
          )
        : null;

const aggregateCausal =
    telemetry.climate_aggregate &&
    telemetry.climate_aggregate.available === true &&
    telemetry.climate_aggregate.causal === true;


// ==================================================
// ENERGY INTEGRATOR
// ==================================================

const energy =
    flow.get(
        "pr_ac_energy_integrator"
    ) || null;

const energyWh =
    energy
        ? finiteOrNull(energy.energy_wh)
        : null;

const energySamples =
    energy
        ? finiteOrNull(energy.samples)
        : null;

const rejectedIntervals =
    energy
        ? finiteOrNull(
            energy.rejected_intervals
          )
        : null;

const energyLastRxMs =
    energy
        ? finiteOrNull(
            energy.last_rx_ms
          )
        : null;

const energySessionId =
    energy &&
    energy.session_id !== undefined &&
    energy.session_id !== null
        ? String(energy.session_id)
        : null;

const energyAgeS =
    energyLastRxMs !== null
        ? (now - energyLastRxMs) / 1000
        : null;

const energyCausal =
    energyLastRxMs !== null &&
    energyLastRxMs <= now;


// ==================================================
// OUTPUT ACCUMULATORS
// ==================================================

const fileMessages = [];

let completedCount = 0;
let invalidCount = 0;
let anchorCreated = false;


// ==================================================
// PROCESS EXISTING PENDING ANCHORS FIRST
// ==================================================

const stillPending = [];

for (const anchor of collector.pending) {

    const elapsedMs =
        now -
        Number(anchor.anchor_timestamp_ms);

    /*
     * Track regime evolution as metadata.
     * Regime changes do NOT automatically invalidate
     * the future-energy target.
     */
    if (
        commandRaw !== null &&
        commandRaw !== anchor.command_raw
    ) {
        anchor.command_changed_during_horizon = true;
    }

    if (
        logicalState !== null &&
        logicalState !== anchor.logical_state
    ) {
        anchor.logical_state_changed_during_horizon = true;
    }


    // ----------------------------------------------
    // Invalid clock
    // ----------------------------------------------

    if (
        !Number.isFinite(elapsedMs) ||
        elapsedMs < 0
    ) {

        fileMessages.push(
            makeFileMessage(
                terminalRecord(
                    anchor,
                    "INVALID",
                    "INVALID_ELAPSED_TIME"
                )
            )
        );

        invalidCount++;
        continue;
    }


    // ----------------------------------------------
    // Integrator session continuity
    // ----------------------------------------------

    if (
        !energySessionId ||
        energySessionId !==
            anchor.energy_integrator_session_id
    ) {

        fileMessages.push(
            makeFileMessage(
                terminalRecord(
                    anchor,
                    "INVALID",
                    "ENERGY_INTEGRATOR_SESSION_CHANGED",
                    {
                        energy_integrator_session_id_end:
                            energySessionId
                    }
                )
            )
        );

        invalidCount++;
        continue;
    }


    // ----------------------------------------------
    // Counter reset
    // ----------------------------------------------

    if (
        energyWh === null ||
        energyWh <
            Number(anchor.energy_start_wh)
    ) {

        fileMessages.push(
            makeFileMessage(
                terminalRecord(
                    anchor,
                    "INVALID",
                    "ENERGY_COUNTER_RESET_OR_INVALID",
                    {
                        energy_end_wh:
                            energyWh
                    }
                )
            )
        );

        invalidCount++;
        continue;
    }


    // ----------------------------------------------
    // Sample counter restart
    // ----------------------------------------------

    if (
        energySamples === null ||
        energySamples <
            Number(
                anchor.energy_integrator_samples_start
            )
    ) {

        fileMessages.push(
            makeFileMessage(
                terminalRecord(
                    anchor,
                    "INVALID",
                    "ENERGY_INTEGRATOR_RESTARTED",
                    {
                        energy_integrator_samples_end:
                            energySamples
                    }
                )
            )
        );

        invalidCount++;
        continue;
    }


    // ----------------------------------------------
    // Telemetry gap
    // ----------------------------------------------

    if (
        rejectedIntervals === null ||
        rejectedIntervals >
            Number(
                anchor.energy_rejected_intervals_start
            )
    ) {

        fileMessages.push(
            makeFileMessage(
                terminalRecord(
                    anchor,
                    "INVALID",
                    "ENERGY_TELEMETRY_GAP_DURING_TARGET",
                    {
                        energy_rejected_intervals_end:
                            rejectedIntervals
                    }
                )
            )
        );

        invalidCount++;
        continue;
    }


    // ----------------------------------------------
    // Not at horizon yet
    // ----------------------------------------------

    if (elapsedMs < HORIZON_MS) {
        stillPending.push(anchor);
        continue;
    }


    // ----------------------------------------------
    // Too late
    // ----------------------------------------------

    if (
        elapsedMs >
        HORIZON_MS +
        MAX_COMPLETION_DELAY_MS
    ) {

        fileMessages.push(
            makeFileMessage(
                terminalRecord(
                    anchor,
                    "INVALID",
                    "COMPLETION_TOO_LATE",
                    {
                        completion_elapsed_s:
                            elapsedMs / 1000
                    }
                )
            )
        );

        invalidCount++;
        continue;
    }


    // ----------------------------------------------
    // At horizon, but energy source temporarily stale:
    // keep pending while still within +2 min window.
    // ----------------------------------------------

    if (
        !energyCausal ||
        energyAgeS === null ||
        energyAgeS > MAX_AC_AGE_S
    ) {
        stillPending.push(anchor);
        continue;
    }


    // ----------------------------------------------
    // COMPLETE causal target
    // ----------------------------------------------

    const energy30mKwh =
        (
            energyWh -
            Number(anchor.energy_start_wh)
        ) / 1000;

    const complete =
        terminalRecord(
            anchor,
            "COMPLETE",
            null,
            {
                completion_timestamp_ms:
                    now,

                completion_elapsed_s:
                    elapsedMs / 1000,

                command_raw_end:
                    commandRaw,

                logical_state_end:
                    logicalState,

                energy_end_wh:
                    energyWh,

                energy_30m_kwh:
                    energy30mKwh,

                energy_integrator_samples_end:
                    energySamples,

                energy_rejected_intervals_end:
                    rejectedIntervals,

                energy_integrator_session_id_end:
                    energySessionId
            }
        );

    fileMessages.push(
        makeFileMessage(complete)
    );

    completedCount++;
}


// ==================================================
// REPLACE PENDING LIST WITH SURVIVORS
// ==================================================

collector.pending = stillPending;


// ==================================================
// DETERMINE WHETHER CURRENT T0 CAN BECOME A NEW ANCHOR
// ==================================================

const anchorBlockers = [];

const supportedCommand =
    NEW_REGIME_COMMANDS.includes(
        commandRaw
    );

const nightDry =
    logicalState === "NIGHT_DRY";

const commandObserved =
    telemetry.ac_command &&
    telemetry.ac_command.observed_since_boot === true &&
    telemetry.ac_command.effective_observed === true &&
    commandRaw !== null &&
    commandRaw.length > 0;

const acReady =
    acW !== null &&
    acCausal &&
    acAgeS !== null &&
    acAgeS >= 0 &&
    acAgeS <= MAX_AC_AGE_S;

const rhReady =
    rh !== null &&
    rhCausal &&
    rhAgeS !== null &&
    rhAgeS >= 0 &&
    rhAgeS <= MAX_RH_AGE_S;

const aggregateReady =
    aggregateCausal &&
    aggregateAgeS !== null &&
    aggregateAgeS >= 0 &&
    aggregateAgeS <= MAX_AGGREGATE_AGE_S &&
    humidex !== null;

const energyReady =
    energyWh !== null &&
    energySamples !== null &&
    rejectedIntervals !== null &&
    energySessionId !== null &&
    energyCausal &&
    energyAgeS !== null &&
    energyAgeS >= 0 &&
    energyAgeS <= MAX_AC_AGE_S;


if (!commandObserved) {
    anchorBlockers.push(
        "AC_COMMAND_NOT_OBSERVED"
    );
}

if (
    commandObserved &&
    !supportedCommand
) {
    anchorBlockers.push(
        "COMMAND_NOT_IN_NEW_REGIME_SET"
    );
}

if (!nightDry) {
    anchorBlockers.push(
        "LOGICAL_STATE_NOT_NIGHT_DRY"
    );
}

if (!acReady) {
    anchorBlockers.push(
        "AC_POWER_NOT_CAUSALLY_READY"
    );
}

if (!rhReady) {
    anchorBlockers.push(
        "BEDROOM_RH_NOT_CAUSALLY_READY"
    );
}

if (!aggregateReady) {
    anchorBlockers.push(
        "CLIMATE_AGGREGATE_NOT_CAUSALLY_READY"
    );
}

if (!energyReady) {
    anchorBlockers.push(
        "ENERGY_INTEGRATOR_NOT_READY"
    );
}


// ==================================================
// RATE LIMIT NEW ANCHORS
// ==================================================

let intervalReady = true;

if (
    collector.last_anchor_ms !== null
) {

    const sinceLast =
        now -
        Number(
            collector.last_anchor_ms
        );

    intervalReady =
        Number.isFinite(sinceLast) &&
        sinceLast >=
            MIN_ANCHOR_INTERVAL_MS;
}


// ==================================================
// CREATE PENDING ANCHOR
// ==================================================

if (
    anchorBlockers.length === 0 &&
    intervalReady
) {

    collector.sequence++;

    const activeNow =
        acW >= ACTIVE_THRESHOLD_W
            ? 1
            : 0;

    const recordId =
        "NRV1-" +
        String(now) +
        "-" +
        String(collector.sequence);

    const anchor = {

        schema_version:
            SCHEMA,

        record_id:
            recordId,

        record_status:
            "PENDING",

        invalid_reason:
            null,

        anchor_timestamp_ms:
            now,

        command_raw:
            commandRaw,

        command_rx_ms:
            commandRxMs,

        logical_state:
            logicalState,

        active_now:
            activeNow,

        active_threshold_w:
            ACTIVE_THRESHOLD_W,

        ac_w_now:
            acW,

        rh_bed_pct:
            rh,

        humidex_bed:
            humidex,

        cmd_293:
            null,

        cmd_293_status:
            "NOT_AUDITED_FOR_NEW_REGIME",

        source_age_s: {
            ac_power:
                acAgeS,

            bedroom_rh:
                rhAgeS,

            climate_aggregate:
                aggregateAgeS,

            energy_integrator:
                energyAgeS
        },

        energy_start_wh:
            energyWh,

        energy_integrator_samples_start:
            energySamples,

        energy_rejected_intervals_start:
            rejectedIntervals,

        energy_integrator_session_id:
            energySessionId,

        target_horizon_min:
            30,

        completion_timestamp_ms:
            null,

        energy_end_wh:
            null,

        energy_30m_kwh:
            null,

        command_changed_during_horizon:
            false,

        logical_state_changed_during_horizon:
            false,

        collector_policy: {
            ac_max_age_s:
                MAX_AC_AGE_S,

            rh_max_age_s:
                MAX_RH_AGE_S,

            aggregate_max_age_s:
                MAX_AGGREGATE_AGE_S,

            active_threshold_w:
                ACTIVE_THRESHOLD_W
        },

        safety: {
            observation_only:
                true,

            production_state_modified:
                false,

            mqtt_command_published:
                false,

            actuator_path:
                false,

            commands_enabled:
                false
        }
    };

    collector.pending.push(anchor);

    collector.last_anchor_ms =
        now;

    /*
     * Append the PENDING anchor immediately.
     * This means tonight's T0 observations are
     * already persisted even before +30 min.
     */
    fileMessages.push(
        makeFileMessage(anchor)
    );

    anchorCreated = true;
}


// ==================================================
// SAVE COLLECTOR STATE
// ==================================================

const collectorAfter =
    JSON.stringify(collector);

const persistentStateChanged =
    collectorAfter !== collectorBefore;

if (persistentStateChanged) {

    flow.set(
        STATE_KEY,
        collector,
        "file"
    );
}


// ==================================================
// DIAGNOSTIC OUTPUT
// ==================================================

const diagnostic = {

    timestamp_ms:
        now,

    wp:
        "WP2D.5B.6B",

    mode:
        "SHADOW",

    anchor_created:
        anchorCreated,

    pending_count:
        collector.pending.length,

    completed_this_cycle:
        completedCount,

    invalid_this_cycle:
        invalidCount,

    records_written_this_cycle:
        fileMessages.length,

    current_command:
        commandRaw,

    logical_state:
        logicalState,

    anchor_blockers:
        anchorBlockers,

    interval_ready:
        intervalReady,

    energy_integrator: {
        session_id:
            energySessionId,

        energy_wh:
            energyWh,

        samples:
            energySamples,

        rejected_intervals:
            rejectedIntervals,

        age_s:
            energyAgeS
    },

    collector_policy: {
        allowed_commands:
            NEW_REGIME_COMMANDS,

        horizon_min:
            30,

        completion_delay_max_min:
            2,

        anchor_interval_min_s:
            MIN_ANCHOR_INTERVAL_MS / 1000,

        ac_max_age_s:
            MAX_AC_AGE_S,

        rh_max_age_s:
            MAX_RH_AGE_S,

        aggregate_max_age_s:
            MAX_AGGREGATE_AGE_S
    },

    persistence: {
