const MAX_AC_AGE_S = 60;


// --------------------------------------------------
// helpers
// --------------------------------------------------

function finite(v) {

    if (
        v === null ||
        v === undefined ||
        v === ""
    ) {
        return null;
    }

    const n = Number(v);

    return Number.isFinite(n)
        ? n
        : null;
}

function median(values) {

    const a =
        values
            .map(Number)
            .filter(Number.isFinite)
            .sort((x, y) => x - y);

    if (!a.length) {
        return null;
    }

    const m = Math.floor(a.length / 2);

    return a.length % 2
        ? a[m]
        : (a[m - 1] + a[m]) / 2;
}

function ageSeconds(ts) {

    if (
        ts === null ||
        ts === undefined ||
        ts === ""
    ) {
        return null;
    }

    const n = Number(ts);

    if (
        !Number.isFinite(n) ||
        n > now
    ) {
        return null;
    }

    return (now - n) / 1000;
}


// --------------------------------------------------
// identify predictor message
// --------------------------------------------------

const payload =
    msg &&
    msg.payload &&
    typeof msg.payload === "object"
        ? msg.payload
        : {};

let predictorSource = null;
let predictorReady = false;
let predictedE30 = null;
let commandRaw = null;
let predictorReason = null;
let generalizationValidated = false;


// Candidate 25dry
if (
    payload.source ===
    "PR Candidate 25dry Runtime"
) {

    predictorSource =
        "CANDIDATE_25DRY_V1";

    commandRaw =
        payload.command_raw === undefined ||
        payload.command_raw === null
            ? null
            : String(payload.command_raw).trim();

    predictedE30 =
        finite(
            payload.E_AC_pred_30m_kwh
        );

    generalizationValidated =
        payload.generalization_validated === true;

    predictorReady =
        payload.ok === true &&
        payload.prediction_allowed === true &&
        commandRaw === "25dry" &&
        predictedE30 !== null;

    predictorReason =
        predictorReady
            ? "CANDIDATE_READY"
            : (
                payload.reason ||
                "CANDIDATE_NOT_READY"
              );
}


// Historical Champion SHADOW Engine
else if (
    payload.predictor &&
    typeof payload.predictor === "object"
) {

    predictorSource =
        "HISTORICAL_CHAMPION";

    commandRaw =
        payload.model_input &&
        payload.model_input.command_raw !== undefined &&
        payload.model_input.command_raw !== null
            ? String(
                payload.model_input.command_raw
              ).trim()
            : null;

    predictedE30 =
        finite(
            payload.predictor.energy_30m_kwh
        );

    predictorReady =
        payload.predictor.model_ready === true &&
        predictedE30 !== null;

    predictorReason =
        predictorReady
            ? "CHAMPION_READY"
            : (
                payload.predictor.reason ||
                "CHAMPION_NOT_READY"
              );
}

else {

    predictorSource =
        "UNKNOWN";

    predictorReason =
        "UNSUPPORTED_PREDICTOR_MESSAGE";
}


// --------------------------------------------------
// telemetry
// --------------------------------------------------

const aggregate =
    flow.get(
        "pr_climate_aggregate"
    ) || null;

const aggregateRx =
    flow.get(
        "pr_climate_aggregate_rx_ms"
    );

const acW =
    finite(
        flow.get(
            "pr_ac_power_w"
        )
    );

const acRx =
    flow.get(
        "pr_ac_power_rx_ms"
    );

const aggregateAge =
    ageSeconds(aggregateRx);

const acAge =
    ageSeconds(acRx);

const aggregateFresh =
    aggregate !== null &&
    aggregateAge !== null &&
    aggregateAge <=
        MAX_AGGREGATE_AGE_S;

const acFresh =
    acW !== null &&
    acAge !== null &&
    acAge <= MAX_AC_AGE_S;


// --------------------------------------------------
// aggregate energy fields
// --------------------------------------------------

const energy =
    aggregate &&
    aggregate.metriche_elettriche &&
    typeof aggregate.metriche_elettriche === "object"
        ? aggregate.metriche_elettriche
        : {};

const soc =
    finite(
        energy.powerwall_soc_percent
    );

const houseW =
    finite(
        energy.consumo_casa_w
    );

const pvW =
    finite(
        energy.produzione_fv_w
    );

const batteryW =
    finite(
        energy.battery_power_w
    );


// --------------------------------------------------
// robust current base load
//
// independent direct AC measurement;
// reject negative transition artifacts.
// 90-minute rolling median.
// persistent across restart.
// --------------------------------------------------

let baseSamples =
    flow.get(
        "pr_reserve_base_samples_v1",
        "file"
    ) || [];

const nonAcRawW =
    houseW !== null &&
    acW !== null
        ? houseW - acW
        : null;

if (
    nonAcRawW !== null &&
    nonAcRawW >= 0 &&
    nonAcRawW <= 4000
) {

    baseSamples.push({
        ts_ms: now,
        w: nonAcRawW
    });
}

baseSamples =
    baseSamples
        .filter(
            x =>
                x &&
                Number.isFinite(
                    Number(x.ts_ms)
                ) &&
                now -
                Number(x.ts_ms)
                    <=
                90 * 60 * 1000
        )
        .slice(-180);

flow.set(
    "pr_reserve_base_samples_v1",
    baseSamples,
    "file"
);

const baseMedianW =
    median(
        baseSamples.map(x => x.w)
    );

const baseKw =
    baseMedianW === null
        ? null
        : baseMedianW / 1000;


// --------------------------------------------------
// T2 causal online learning
//
// Historical recovered contract:
// first sustained morning point with
// PV > 200 W and battery <= 100 W,
// confirmed for 10 minutes.
//
// Last 7 valid observations;
// update after >=3 observations.
// --------------------------------------------------

const d =
    new Date(now);

const hour =
    d.getHours();

const minuteOfDay =
    hour * 60 +
    d.getMinutes();

const nightWindow =
    hour >= 22 ||
    hour < 8;

const localDate =
    [
        d.getFullYear(),
        String(
            d.getMonth() + 1
        ).padStart(2, "0"),
        String(
            d.getDate()
        ).padStart(2, "0")
    ].join("-");


let t2Prior =
    finite(
        flow.get(
            "pr_reserve_t2_prior_min_v1",
            "file"
        )
    );

if (t2Prior === null) {

    // 07:30 bootstrap.
    t2Prior = 450;

    flow.set(
        "pr_reserve_t2_prior_min_v1",
        t2Prior,
        "file"
    );
}


let t2Candidate =
    flow.get(
        "pr_reserve_t2_candidate_v1",
        "file"
    ) || null;

let t2History =
    flow.get(
        "pr_reserve_t2_history_v1",
        "file"
    ) || [];


if (
    hour >= 5 &&
    hour < 12 &&
    pvW !== null &&
    batteryW !== null
) {

    const supportSeen =
        pvW > 200 &&
        batteryW <= 100;

    if (supportSeen) {

        if (
            !t2Candidate ||
            t2Candidate.date !==
                localDate
        ) {

            t2Candidate = {
                date: localDate,
                start_ms: now,
                min_of_day:
                    minuteOfDay
            };

            flow.set(
                "pr_reserve_t2_candidate_v1",
                t2Candidate,
                "file"
            );
        }

        else if (
            now -
            Number(
                t2Candidate.start_ms
            )
            >=
            10 * 60 * 1000
        ) {

            const already =
                t2History.some(
                    x =>
                        x &&
                        x.date ===
                            localDate
                );

            if (!already) {

                t2History.push({
                    date:
                        localDate,
                    t2_min:
                        Number(
                            t2Candidate
                                .min_of_day
                        )
                });

                t2History =
                    t2History.slice(-30);

                flow.set(
                    "pr_reserve_t2_history_v1",
                    t2History,
                    "file"
                );

                const recent =
                    t2History
                        .slice(-7)
                        .map(
                            x =>
                                Number(
                                    x.t2_min
                                )
                        )
                        .filter(
                            Number.isFinite
                        );

                if (
                    recent.length >= 3
                ) {

                    const learned =
                        median(recent);

                    if (
                        learned !== null
                    ) {

                        t2Prior =
                            learned;

                        flow.set(
                            "pr_reserve_t2_prior_min_v1",
                            t2Prior,
                            "file"
                        );
                    }
                }
            }
        }
    }

    else if (
        t2Candidate &&
        t2Candidate.date ===
            localDate
    ) {

        t2Candidate = null;

        flow.set(
            "pr_reserve_t2_candidate_v1",
            null,
            "file"
        );
    }
}


// --------------------------------------------------
// continuous night clock
// --------------------------------------------------

let clockContinuous =
    minuteOfDay;

if (hour < 12) {
    clockContinuous += 1440;
}

let t2Continuous =
    t2Prior;

if (t2Prior < 720) {
    t2Continuous += 1440;
}


// --------------------------------------------------
// energy reserve
// --------------------------------------------------

const batteryEnergyNow =
    soc === null
        ? null
        :
        CAPACITY_KWH *
        soc / 100;

const hardFloorEnergy =
    CAPACITY_KWH *
    HARD_SOC_PCT /
    100;

const supportHours =
    baseKw === null
        ? null
        :
        Math.max(
            t2Continuous -
            clockContinuous,
            0
        ) / 60;

const supportPredKwh =
    supportHours === null
        ? null
        :
        baseKw *
        supportHours;


// No causal P90 series exists yet.
// Frozen-model fail-safe bootstrap floor.
const riskKwh =
    RISK_FLOOR_KWH;

const riskSource =
    "BOOTSTRAP_FLOOR_NO_CAUSAL_HISTORY";


const reserveKwh =
    supportPredKwh === null
        ? null
        :
        supportPredKwh +
        riskKwh;

const budgetKwh =
    batteryEnergyNow === null ||
    reserveKwh === null
        ? null
        :
        Math.max(
            batteryEnergyNow -
            hardFloorEnergy -
            reserveKwh,
            0
        );


// --------------------------------------------------
// final SHADOW decision
// --------------------------------------------------

const reasons = [];

if (!nightWindow) {
    reasons.push(
        "OUTSIDE_NIGHT_DRY_WINDOW"
    );
}

if (!aggregateFresh) {
    reasons.push(
        "CLIMATE_AGGREGATE_NOT_FRESH"
    );
}

if (!acFresh) {
    reasons.push(
        "AC_POWER_NOT_FRESH"
    );
}

if (soc === null) {
    reasons.push(
        "SOC_NOT_AVAILABLE"
    );
}

if (houseW === null) {
    reasons.push(
        "HOUSE_POWER_NOT_AVAILABLE"
    );
}

if (baseKw === null) {
    reasons.push(
        "BASE_MODEL_NOT_READY"
    );
}

if (budgetKwh === null) {
    reasons.push(
        "ENERGY_BUDGET_NOT_READY"
    );
}

if (!predictorReady) {
    reasons.push(
        predictorReason ||
        "PREDICTOR_NOT_READY"
    );
}

if (
    soc !== null &&
    soc <= HARD_SOC_PCT
) {
    reasons.push(
        "HARD_SOC_FLOOR"
    );
}


const calculationReady =
    reasons.length === 0;


const wouldAllow =
    calculationReady &&
    predictedE30 !== null &&
    budgetKwh !== null
        ?
        predictedE30 +
        MARGIN_KWH <=
        budgetKwh
        :
        false;


// --------------------------------------------------
// output
// --------------------------------------------------

msg.topic =
    "pr/shadow/final_decision";

msg.payload = {

    schema:
        "domopi.predictive_reserve.final_shadow_decision.v1",

    timestamp_ms:
        now,

    mode:
        "SHADOW",

    control_effect:
        "NONE_SHADOW_ONLY",


    regime: {

        command_raw:
            commandRaw,

        predictor_source:
            predictorSource,

        predictor_ready:
            predictorReady,

        generalization_validated:
            generalizationValidated
    },


    prediction: {

        E_AC_pred_30m_kwh:
            predictedE30,

        margin_kwh:
            MARGIN_KWH
    },


    reserve: {

        capacity_reference_kwh:
            CAPACITY_KWH,

        soc_percent:
            soc,

        battery_energy_now_kwh:
            batteryEnergyNow,

        hard_soc_floor_percent:
            HARD_SOC_PCT,

        hard_floor_energy_kwh:
            hardFloorEnergy,

        base_current_w:
            baseMedianW,

        t2_prior_minute_of_day:
            t2Prior,

        t2_history_count:
            t2History.length,

        support_hours_remaining:
            supportHours,

        E_support_pred_kwh:
            supportPredKwh,

        E_risk_kwh:
            riskKwh,

        risk_source:
            riskSource,

        E_reserve_kwh:
            reserveKwh,

        E_budget_kwh:
            budgetKwh
    },


    decision: {

        calculation_ready:
            calculationReady,

        would_allow_energy:
            wouldAllow,

        authorization_allowed:
            false,

        reasons:
            reasons
    },


    telemetry: {

        aggregate_age_s:
            aggregateAge,

        ac_power_age_s:
            acAge,

        house_power_w:
            houseW,

        ac_power_w:
            acW,

        pv_power_w:
            pvW,

        battery_power_w:
            batteryW
    },


    safety: {

        shadow_only:
            true,

        mqtt_command_published:
            false,

        actuator_path:
            false,

        production_state_modified:
            false
    }
};


node.status({

    fill:
        calculationReady
            ? "blue"
            : "yellow",

    shape:
        calculationReady
            ? "dot"
            : "ring",

    text:
        calculationReady
            ?
            (
                "SHADOW " +
                (
                    wouldAllow
                        ? "ALLOW"
                        : "DENY"
                ) +
                " budget=" +
                budgetKwh
                    .toFixed(2) +
                "kWh"
            )
            :
            "SHADOW NOT READY"
});


if (msg._pr_prestart) { msg._pr_prestart.final = {command: msg.payload.regime.command_raw, timestamp_ms: msg.payload.timestamp_ms}; }
return msg;

/*
 * Predictive Reserve
 * PR-OSC.2 - Operational State Contract
 *
 * ACTIVE.4B.2A.1 - Persistent operating mode control
 *
 * Owns the persistent user control flag and operating mode.
 * Final ACTIVE authority belongs exclusively to Shared Arbitration Gate.
 *
 * IMPORTANT:
 * - control_enabled does NOT authorize actuation
 * - control_enabled does NOT publish AC commands
 * - control_enabled does NOT modify AI Climate
 * - missing/invalid persistent control state => false
 * - missing/invalid persistent operating mode => SHADOW
 */

const STORE = "file";

const CONTROL_KEY = "pr_control_enabled";

// ACTIVE.4B.2A.1: independent persistent mode, using file context.
const MODE_KEY = "pr_operating_mode";

const now = Date.now();

/*
 * SOFTWARE-ONLY FAIL-SAFE SELF TEST
 *
 * Simulates an invalid persistent value without touching
 * the real Node-RED file context.
 */
const isInvalidStateSelfTest =
    msg &&
    msg.topic === "pr/selftest/control_invalid";


function parseBooleanStrict(value) {

    if (value === true || value === 1) {
        return true;
    }

    if (value === false || value === 0) {
        return false;
    }

    if (typeof value === "string") {

        const v = value.trim().toLowerCase();

        if (
            v === "true" ||
            v === "1" ||
            v === "on"
        ) {
            return true;
        }

        if (
            v === "false" ||
            v === "0" ||
            v === "off"
        ) {
            return false;
        }
    }

    return null;
}


/*
 * ----------------------------------------------------------
 * 1. READ CURRENT PERSISTENT STATE
 * ----------------------------------------------------------
 */

const storedRaw =
    isInvalidStateSelfTest
        ? "__INVALID_PERSISTENT_VALUE__"
        : flow.get(CONTROL_KEY, STORE);

let controlEnabled =
    parseBooleanStrict(storedRaw);


/*
 * Missing or corrupted state is fail-safe OFF.
 *
 * Persist the normalized OFF so subsequent boots have
 * an explicit valid value.
 */
if (controlEnabled === null) {

    controlEnabled = false;

    /*
     * In normal runtime, invalid/missing persistent state
     * is normalized and persisted as safe OFF.
     *
     * During software-only self-test, do NOT modify
     * the real persistent context.
     */
    if (!isInvalidStateSelfTest) {

        flow.set(
            CONTROL_KEY,
            false,
            STORE
        );
    }
}


/*
 * ACTIVE.4B.2A.1: persisted mode must be canonical.
 * Missing, invalid or corrupt values fail safe to SHADOW and are repaired.
 * Command input normalization is separate from persistent-state validation.
 */
let operatingMode = flow.get(MODE_KEY, STORE);
if (operatingMode !== "SHADOW" && operatingMode !== "ACTIVE") {
    operatingMode = "SHADOW";
    flow.set(MODE_KEY, operatingMode, STORE);
}


/*
 * ----------------------------------------------------------
 * 2. OPTIONAL CONTROL COMMAND
 *
 * Only this explicit internal topic may modify the flag.
 * Later the Digital Twin Router will translate its command
 * into this contract.
 * ----------------------------------------------------------
 */

let commandAccepted = false;
let commandRejected = false;

if (msg.topic === "pr/control_enabled/set") {

    const requested =
        parseBooleanStrict(msg.payload);

    if (requested === null) {

        commandRejected = true;

    } else {

        controlEnabled = requested;

        flow.set(
            CONTROL_KEY,
            controlEnabled,
            STORE
        );

        commandAccepted = true;
    }
}


/*
 * ACTIVE.4B.2A.1: explicit internal mode command, independent of control.
 * Reject non-string/unknown payloads without changing the normalized mode.
 * Generic accepted/rejected describe whichever command was received.
 */
if (msg.topic === "pr/operating_mode/set") {
    const requestedMode = typeof msg.payload === "string"
        ? msg.payload.trim().toUpperCase()
        : null;

    if (requestedMode === "SHADOW" || requestedMode === "ACTIVE") {
        operatingMode = requestedMode;
        flow.set(MODE_KEY, operatingMode, STORE);
        commandAccepted = true;
    } else {
        commandRejected = true;
    }
}


/*
 * ----------------------------------------------------------
 * 3. OBSERVATIONAL OPERATING STATE
 *
 * ACTIVE.4B.2A.1: mode and control request remain independent.
 *
 * control_enabled=true therefore means:
 * "user requests PR control; final eligibility is evaluated by the Gate"
 *
 * It does NOT mean that authority currently exists.
 * ----------------------------------------------------------
 */

const championReady =
    flow.get("pr_champion_artifact_ready") === true;

const knnReady =
    flow.get("pr_knn_runtime_ready") === true;

const shadowReady =
    championReady && knnReady;


/*
 * ----------------------------------------------------------
 * 4. PUBLIC OPERATIONAL CONTRACT
 * ----------------------------------------------------------
 */

const state = {

    schema:
        "domopi.predictive_reserve.operational_state.v1",

    control_enabled:
        controlEnabled,

    operating_mode:
        operatingMode,

    ready:
        shadowReady,

    // ACTIVE.4B.2A.1: observational request only; never grant authority here.
    authority: {
        requested:
            controlEnabled,

        allowed:
            false,

        reason:
            operatingMode === "SHADOW"
                ? "SHADOW_ONLY"
                : "DELEGATED_TO_ARBITRATION_GATE"
    },

    safety: {
        shadow_only:
            operatingMode === "SHADOW",

        mqtt_command_published:
            false,

        actuator_path:
            false,

        production_state_modified:
            false
    },

    command: {
        accepted:
            commandAccepted,

        rejected:
            commandRejected
    },

    updated_at_ms:
        now
};


/*
 * Runtime copy for other PR nodes.
 *
 * ACTIVE.4B.2A.1: persistent configuration is pr_control_enabled and
 * pr_operating_mode. Final authority is owned only by the Arbitration Gate.
 */
flow.set(
    "pr_operational_state",
    state
);


node.status({

    fill:
        controlEnabled ? "blue" : "grey",

    shape:
        shadowReady ? "dot" : "ring",

    text:
        operatingMode + " control=" +
        (controlEnabled ? "ON" : "OFF")
});


msg.topic =
    "pr/operational_state";

msg.payload =
    state;

return msg;

/*
 * Predictive Reserve
 * PR-ARB.2A - Arbitration Snapshot
 *
 * SHADOW / CONTRACT ONLY
 *
 * No MQTT OUT
 * No actuator
 * No AI Climate modification
 */

const now = Date.now();

const p =
    msg &&
    msg.payload &&
    typeof msg.payload === "object"
        ? msg.payload
        : null;

if (!p) {
    return null;
}

const operational =
    flow.get("pr_operational_state") || null;

const operatingMode =
    operational &&
        operational.operating_mode === "ACTIVE"
        ? "ACTIVE"
        : "SHADOW";

const controlEnabled =
    operational &&
    operational.control_enabled === true;

const prReady =
    operational &&
    operational.ready === true;

const decision =
    p.decision &&
    typeof p.decision === "object"
        ? p.decision
        : {};

const calculationReady =
    decision.calculation_ready === true;

const wouldAllowEnergy =
    decision.would_allow_energy === true;

const sourceReasons =
    Array.isArray(decision.reasons)
        ? decision.reasons.slice()
        : [];

let reason;

if (!controlEnabled) {
    reason = "PR_CONTROL_DISABLED";
}
else if (!prReady) {
    reason = "PR_NOT_READY";
}
else if (!calculationReady) {
    reason = "DECISION_NOT_READY";
}
else if (!wouldAllowEnergy) {
    reason = "ENERGY_DENY";
}
else {
    reason = "ALLOW";
}

const allowNightDryStart =
    controlEnabled &&
    prReady &&
    calculationReady &&
    wouldAllowEnergy;

const snapshot = {
    schema:
        "domopi.predictive_reserve.arbitration_snapshot.v1",

    timestamp_ms:
        now,

    control_enabled:
        controlEnabled,

    pr_ready:
        prReady,

    decision: {
        valid:
            prReady &&
            calculationReady,

        allow_night_dry_start:
            allowNightDryStart,

        reason:
            reason
    },

    source: {
        final_decision_timestamp_ms:
            Number.isFinite(Number(p.timestamp_ms))
                ? Number(p.timestamp_ms)
                : null,

        calculation_ready:
            calculationReady,

        would_allow_energy:
            wouldAllowEnergy,

        reasons:
            sourceReasons
    },

    safety: {
        shadow_only:
            operatingMode === "SHADOW",

        actuator_path:
            false,

        ai_climate_modified:
            false
    }
};

flow.set(
    "pr_arbitration_snapshot",
    snapshot
);

msg.topic =
    "pr/arbitration_snapshot";

msg.payload =
    snapshot;

if (msg._pr_prestart) { msg._pr_prestart.snapshot = {timestamp_ms: msg.payload.timestamp_ms, final_timestamp_ms: msg.payload.source.final_decision_timestamp_ms}; }
return msg;

/*
 * PR-ARB.3B
 * Arbitration Consumer Self-Test
 *
 * TEST ONLY
 * No actuator
 * No MQTT OUT
 * No AI Climate modification
 */

const MAX_SNAPSHOT_AGE_MS = 120000;
const NOW = Date.now();

function evaluatePrNightDry(
    controlEnabled,
    snapshot,
    now
) {
    if (controlEnabled !== true) {
        return {
            action: "BYPASS",
            reason: "PR_CONTROL_DISABLED"
        };
    }

    if (
        !snapshot ||
        typeof snapshot !== "object"
    ) {
        return {
            action: "DENY",
            reason: "SNAPSHOT_INVALID"
        };
    }

    if (
        snapshot.schema !==
        "domopi.predictive_reserve.arbitration_snapshot.v1"
    ) {
        return {
            action: "DENY",
            reason: "SNAPSHOT_INVALID"
        };
    }

    const ts =
        Number(snapshot.timestamp_ms);

    if (
        !Number.isFinite(ts) ||
        ts > now
    ) {
        return {
            action: "DENY",
            reason: "SNAPSHOT_INVALID"
        };
    }

    if (
        (now - ts) > MAX_SNAPSHOT_AGE_MS
    ) {
        return {
            action: "DENY",
            reason: "SNAPSHOT_STALE"
        };
    }

    if (
        !snapshot.decision ||
        snapshot.decision.valid !== true
    ) {
        return {
            action: "DENY",
            reason:
                snapshot.decision &&
                snapshot.decision.reason
                    ? snapshot.decision.reason
                    : "DECISION_NOT_READY"
        };
    }

    if (
        snapshot.decision.allow_night_dry_start !== true
    ) {
        return {
            action: "DENY",
            reason:
                snapshot.decision.reason ||
                "ENERGY_DENY"
        };
    }

    return {
        action: "ALLOW",
        reason: "ALLOW"
    };
}

function makeSnapshot(
    ageMs,
    valid,
    allow,
    reason,
    schema
) {
    return {
