/*
 * PR-ACTIVE.3A
 * Isolated ACTIVE Arbitration Simulation
 *
 * NO global writes
 * NO flow writes
 * NO MQTT
 * NO actuator
 * NO AI Climate state mutation
 */

const GATE_SCHEMA =
    "domopi.predictive_reserve.arbitration_gate.v1";

const SNAPSHOT_SCHEMA =
    "domopi.predictive_reserve.arbitration_snapshot.v1";

const MAX_AGE_MS = 120000;
const nowMs = Date.now();


function evaluate(candidateCommandIR, gate) {

    let action = "DENY";
    let reason = "PR_GATE_INVALID";

    if (
        !gate ||
        typeof gate !== "object" ||
        gate.schema !== GATE_SCHEMA
    ) {
        return { action, reason };
    }

    if (gate.control_enabled !== true) {
        return {
            action: "BYPASS",
            reason: "PR_CONTROL_DISABLED"
        };
    }

    if (gate.effective_authority !== true) {
        return {
            action: "DENY",
            reason: "PR_NOT_AUTHORIZED"
        };
    }

    if (
        !gate.active_regimes ||
        typeof gate.active_regimes !== "object" ||
        !gate.active_regimes[candidateCommandIR] ||
        gate.active_regimes[candidateCommandIR].qualified !== true
    ) {
        return {
            action: "DENY",
            reason: "COMMAND_REGIME_NOT_QUALIFIED"
        };
    }

    const snap = gate.snapshot;

    if (
        !snap ||
        typeof snap !== "object" ||
        snap.schema !== SNAPSHOT_SCHEMA
    ) {
        return {
            action: "DENY",
            reason: "SNAPSHOT_INVALID"
        };
    }

    const ts =
        snap.source &&
        Number.isFinite(
            snap.source.final_decision_timestamp_ms
        )
            ? snap.source.final_decision_timestamp_ms
            : (
                Number.isFinite(snap.timestamp_ms)
                    ? snap.timestamp_ms
                    : null
            );

    if (ts === null) {
        return {
            action: "DENY",
            reason: "SNAPSHOT_INVALID"
        };
    }

    const ageMs = nowMs - ts;

    if (
        ageMs < 0 ||
        ageMs > MAX_AGE_MS
    ) {
        return {
            action: "DENY",
            reason: "SNAPSHOT_STALE"
        };
    }

    if (
        !snap.decision ||
        snap.decision.valid !== true
    ) {
        return {
            action: "DENY",
            reason: "DECISION_NOT_READY"
        };
    }

    if (
        snap.decision.allow_night_dry_start === true
    ) {
        return {
            action: "ALLOW",
            reason:
                snap.decision.reason || "ALLOW"
        };
    }

    return {
        action: "DENY",
        reason:
            snap.decision.reason || "ENERGY_DENY"
    };
}


