/*
 * PR-ACTIVE.3B.1
 * Consumer Commit Boundary Self-Test
 *
 * Isolated:
 * - no flow/global writes
 * - no MQTT
 * - no Broadlink
 * - no production state mutation
 */

function simulate(candidateCommandIR, prAction, prReason) {

    // Equivalent initial production condition.
    let statoAttuale = "OFF";
    let comandoIR = null;

    let condizionatoreStateWritten = false;
    let ultimoAvvioWritten = false;

    let motivoAc = "PRONTO_ACCENSIONE_NIGHT_DRY";

    // Exact production commit boundary.
    if (
        prAction === "BYPASS" ||
        prAction === "ALLOW"
    ) {
        statoAttuale = "NIGHT_DRY";

        // Simulation only: represent the writes,
        // never perform them.
        condizionatoreStateWritten = true;
        ultimoAvvioWritten = true;

        comandoIR = candidateCommandIR;

        if (prAction === "ALLOW") {
            motivoAc =
                "ESECUZIONE_ACCENSIONE_NOTTURNA_PR";
        } else {
            motivoAc =
                "ESECUZIONE_ACCENSIONE_NOTTURNA";
        }
    }
    else {
        motivoAc =
            "BLOCCO_PR_" + prReason;
    }

    // Equivalent Broadlink creation semantics,
    // but no message is emitted.
    const broadlinkWouldBeProduced =
        comandoIR !== null;

    return {
        stato_attuale: statoAttuale,
        comando_ir: comandoIR,
        motivo_ac: motivoAc,

        simulated_writes: {
            condizionatore_stato:
                condizionatoreStateWritten,
            ultimo_avvio:
                ultimoAvvioWritten
        },

        broadlink_would_be_produced:
            broadlinkWouldBeProduced
    };
}


const tests = [];


function run(name, candidate, action, reason, expected) {

    const actual =
        simulate(
            candidate,
            action,
            reason
        );

    const pass =
        actual.stato_attuale ===
            expected.stato_attuale &&
        actual.comando_ir ===
            expected.comando_ir &&
        actual.simulated_writes.condizionatore_stato ===
            expected.write_state &&
        actual.simulated_writes.ultimo_avvio ===
            expected.write_start &&
        actual.broadlink_would_be_produced ===
            expected.broadlink;

    tests.push({
        name,
        candidate,
        action,
        reason,
        expected,
        actual,
        pass
    });
}


