function numOrNull(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function ageSeconds(rx) {

    /*
     * Missing timestamp must remain UNKNOWN.
     * Do not allow Number(null) -> 0.
     */
    if (
        rx === null ||
        rx === undefined ||
        rx === ""
    ) {
        return null;
    }

    const n = Number(rx);

    if (!Number.isFinite(n)) {
        return null;
    }

    // strict past-only
    if (n > now) {
        return null;
    }

    return (now - n) / 1000;
}

function nested(obj, path) {
    let cur = obj;

    for (const key of path) {
        if (
            cur === null ||
            cur === undefined ||
            typeof cur !== "object" ||
            !(key in cur)
        ) {
            return null;
        }

        cur = cur[key];
    }

    return cur;
}


/*
 * Exact KNN runtime logic transplanted from
 * the already validated PR KNN Self Test.
 */
function predictKnn(modelSpec, allTrainingRows, query) {

    if (
        !modelSpec ||
        !Array.isArray(allTrainingRows)
    ) {
        throw new Error("INVALID_MODEL_SPEC");
    }

    const features =
        modelSpec.features;

    const normalization =
        modelSpec.normalization;

    const condition =
        modelSpec.condition;

    const k =
        Number(modelSpec.k);

    const target =
        modelSpec.target;


    if (
        !Array.isArray(features) ||
        !normalization ||
        !condition ||
        !target
    ) {
        throw new Error(
            "INVALID_MODEL_METADATA"
        );
    }

    if (
        !Number.isFinite(k) ||
        k <= 0
    ) {
        throw new Error("INVALID_K");
    }


    // ==============================================
    // SELECT TRAINING POPULATION
    //
    // Preserve original root row order.
    // This is essential for deterministic tie-break.
    // ==============================================

    const rows =
        allTrainingRows.filter((r) => {

            for (
                const [key, expected]
                of Object.entries(condition)
            ) {

                /*
                 * command_raw is metadata describing
                 * the raw command represented by
                 * historical cmd_293.
                 *
                 * It is NOT present in training_rows,
                 * therefore it is not a row filter.
                 */
                if (key === "command_raw") {
                    continue;
                }

                if (!(key in r)) {
                    return false;
                }

                if (
                    Number.isFinite(Number(expected)) &&
                    Number.isFinite(Number(r[key]))
                ) {
                    if (
                        Number(r[key]) !==
                        Number(expected)
                    ) {
                        return false;
                    }
                }
                else if (
                    String(r[key]) !==
                    String(expected)
                ) {
                    return false;
                }
            }

            return true;
        });


    if (rows.length < k) {
        throw new Error(
            "INSUFFICIENT_TRAINING_ROWS_" +
            rows.length
        );
    }


    // ==============================================
    // STANDARDIZE QUERY
    // ==============================================

    const qz = {};

    for (const f of features) {

        if (!normalization[f]) {
            throw new Error(
                "MISSING_NORMALIZATION_" + f
            );
        }

        const mean =
            Number(normalization[f].mean);

        const std =
            Number(normalization[f].std);

        const value =
            Number(query[f]);

        if (
            !Number.isFinite(mean) ||
            !Number.isFinite(std) ||
            std <= 0 ||
            !Number.isFinite(value)
        ) {
            throw new Error(
                "INVALID_QUERY_FEATURE_" + f
            );
        }

        qz[f] =
            (value - mean) / std;
    }


    // ==============================================
    // DISTANCES
    // ==============================================

    const scored =
        rows.map((r, idx) => {

            let dist = 0;

            for (const f of features) {

                const mean =
                    Number(normalization[f].mean);

                const std =
                    Number(normalization[f].std);

                const rv =
                    Number(r[f]);

                if (!Number.isFinite(rv)) {
                    throw new Error(
                        "INVALID_TRAINING_FEATURE_" +
                        f
                    );
                }

                const rz =
                    (rv - mean) / std;

                const d =
                    rz - qz[f];

                dist += d * d;
            }


            const targetValue =
                Number(r[target]);

            if (
                !Number.isFinite(targetValue)
            ) {
                throw new Error(
                    "INVALID_TARGET"
                );
            }


            return {
                /*
                 * idx follows filtered rows in the same
                 * order as root training_rows.
                 * Therefore equal-distance tie-break
                 * preserves original training order.
                 */
                idx: idx,
                dist: dist,
                target: targetValue
            };
        });


    // ==============================================
    // EXACT ORDER:
    // distance, then original training order
    // ==============================================

    scored.sort((a, b) => {

        if (a.dist < b.dist) {
            return -1;
        }

        if (a.dist > b.dist) {
            return 1;
        }

        return a.idx - b.idx;
    });


    // ==============================================
    // K NEAREST TARGET MEAN
    // ==============================================

    let sum = 0;

    for (let i = 0; i < k; i++) {
        sum += scored[i].target;
    }

    return {
        prediction:
            sum / k,

        training_population:
            rows.length,

        k:
            k
    };
}


