// --------------------------------------------------
// helpers
// --------------------------------------------------

function finite(v) {

    if (
        v === null ||
        v === undefined ||
        v === ""
    ) {
        return null;
    }

    const n = Number(v);

    return Number.isFinite(n)
        ? n
        : null;
}

function median(values) {

    const a =
        values
            .map(Number)
            .filter(Number.isFinite)
            .sort((x, y) => x - y);

    if (!a.length) {
        return null;
    }

    const m = Math.floor(a.length / 2);

    return a.length % 2
        ? a[m]
        : (a[m - 1] + a[m]) / 2;
}

function ageSeconds(ts) {

    if (
        ts === null ||
        ts === undefined ||
        ts === ""
    ) {
        return null;
    }

    const n = Number(ts);

    if (
        !Number.isFinite(n) ||
        n > now
    ) {
        return null;
    }

    return (now - n) / 1000;
}


