if (typeof r.request_id !== 'string' || !r.request_id ||
    r.engine?.command !== r.candidate_command || r.final?.command !== r.candidate_command ||
    r.snapshot?.timestamp_ms !== s.timestamp_ms ||
    r.snapshot?.final_timestamp_ms !== r.final?.timestamp_ms ||
    s.source?.final_decision_timestamp_ms !== r.final?.timestamp_ms) reason = "REQUEST_MISMATCH";
else if (!causal) reason = "SNAPSHOT_INVALID";
else if (now - r.requested_at_ms >= 2000) reason = "PR_PRESTART_TIMEOUT";
else if (g.schema !== "domopi.predictive_reserve.arbitration_gate.v1" ||
    s.schema !== "domopi.predictive_reserve.arbitration_snapshot.v1") reason = "SNAPSHOT_INVALID";
else if (g.control_enabled !== true || s.control_enabled !== true) reason = "PR_CONTROL_DISABLED";
else if (g.active_regimes?.[r.candidate_command]?.qualified !== true) reason = "COMMAND_REGIME_NOT_QUALIFIED";
else if (g.operating_mode !== "ACTIVE") reason = "PR_NOT_AUTHORIZED";
else if (s.pr_ready !== true) reason = "PR_NOT_READY";
else if (s.decision?.valid !== true) reason = "DECISION_NOT_READY";
else if (g.authority_allowed !== true || g.effective_authority !== true) reason = "PR_NOT_AUTHORIZED";
else if (s.decision.allow_night_dry_start !== true) reason = "ENERGY_DENY";
else if (s.safety?.actuator_path !== false) reason = "SNAPSHOT_INVALID";
else reason = "ALLOW";
msg.topic = "pr/prestart_candidate/result";
msg.payload = {
    schema: "domopi.predictive_reserve.prestart_result.v1",
    request_id: r.request_id, evaluated_at_ms: now,
    transition: "OFF_TO_NIGHT_DRY", candidate_command: r.candidate_command,
    action: reason === "ALLOW" ? "ALLOW" : "DENY", reason,
    authority: {operating_mode:g.operating_mode, authority_allowed:g.authority_allowed === true,
        effective_authority:g.effective_authority === true},
    decision: {valid:s.decision?.valid === true, allow_night_dry_start:s.decision?.allow_night_dry_start === true},
    snapshot_timestamp_ms:s.timestamp_ms
};
return msg;

// ACTIVE.4C.2F.2
// Test consentito solo con PR ON e ACTIVE.
// NON richiediamo che il Gate precedente abbia già authority:
// è il nuovo pre-start handshake che deve ricalcolarla.

const testGate =
    global.get("pr_arbitration_gate");

const testOperational =
    flow.get("pr_operational_state");

if (
    !testGate ||
    testGate.schema !==
    "domopi.predictive_reserve.arbitration_gate.v1" ||

    testGate.control_enabled !== true ||

    !testOperational ||
    testOperational.control_enabled !== true ||
    testOperational.operating_mode !== "ACTIVE"
) {
    node.error(
        "TEST_REQUIRES_PR_ON_ACTIVE",
        msg
    );
    return null;
}

const t = Date.now();

msg.topic =
    "pr/prestart_candidate";

const id =
    msg._msgid;

if (
    typeof id !== "string" ||
    !id
) {
    node.error(
        "REQUEST_INVALID",
        msg
    );
    return null;
}

msg.payload = {
    schema:
        "domopi.predictive_reserve.prestart_request.v1",

    request_id:
        id,

    requested_at_ms:
        t,

    prestart_candidate:
        true,

    transition:
        "OFF_TO_NIGHT_DRY",

    command_raw:
        "eco26dry"
};

msg._pr_prestart = {
    request_id:
        id,

    requested_at_ms:
        t,

    candidate_command:
        "eco26dry"
};

return msg;

